1	/**
2	 * Approval state machine (decision #90): the statuses an approval request moves through and who may move it.
3	 *
4	 *   pending   → approved | rejected (Declined) | postponed | ignored | expired
5	 *   postponed → pending (condition met, time reached, or Reopen) | approved | rejected | revoked | postponed (again) | expired
6	 *   ignored   → pending (Reopen) | rejected | postponed | expired
7	 *   approved  → consumed (Used, by the retry) | revoked | expired
8	 *   held      → rejected (Deny) | approved (Vinnie, when the countdown ends) | expired   (veto calls, decision #102)
9	 *   rejected, consumed, revoked, expired: final.
10	 *
11	 * Pure: every function takes the time it should use, so the monitor and the tests share one clock. Nothing here ever
12	 * changes what the approval is bound to (caller, tool, exact arguments, fingerprint, summary); only status, times and
13	 * the postponement record move. Storage applies a result with `replace` (compare-and-set on status + revision), so
14	 * two changes can never both win.
15	 */
16	import { AxHubError } from "./errors.js";
17	import type { Confirmation, ConfirmationStatus, PostponeCondition, Timestamp } from "./model.js";
18	
19	const MIN = 60 * 1000;
20	const HOUR = 60 * MIN;
21	const DAY = 24 * HOUR;
22	
23	/** A request lives at most this long from when it was asked: a postponement can't outlast it. */
24	export const MAX_POSTPONE_MS = 7 * DAY;
25	/** How often the monitor looks at a postponed request's condition. */
26	export const POSTPONE_CHECK_MS = 5 * MIN;
27	/** How often a postponed request reminds the owner. */
28	export const POSTPONE_REMIND_MS = 30 * MIN;
29	/** After this long postponed, the owner must review it (the console blocks until he does). */
30	export const POSTPONE_REVIEW_MS = 2 * HOUR;
31	/** History entries kept per request. */
32	export const APPROVAL_HISTORY_MAX = 30;
33	
34	/** What a person can do from the approvals page. */
35	export type ApprovalAction = "approve" | "decline" | "postpone" | "ignore" | "revoke" | "reopen" | "deny";
36	export const APPROVAL_ACTIONS: readonly ApprovalAction[] = ["approve", "decline", "postpone", "ignore", "revoke", "reopen", "deny"];
37	
38	/**
39	 * What the hub does by itself. The monitor never approves. `release` and `lapse` are Vinnie's (decision #102): a veto
40	 * call whose countdown ended runs (`release`, held → approved, used at once by the run) or, when the hub was down past
41	 * its time by more than a minute, expires (`lapse`).
42	 */
43	export type ApprovalSystemAction = "resume" | "check" | "remind" | "release" | "lapse";
44	
45	/** Statuses that are over: nothing moves them again. */
46	export const FINAL_APPROVAL_STATUSES: readonly ConfirmationStatus[] = ["rejected", "consumed", "revoked", "expired"];
47	
48	/** Statuses that time out at `expiresAt`. */
49	export const LIVE_APPROVAL_STATUSES: readonly ConfirmationStatus[] = ["pending", "approved", "postponed", "ignored", "held"];
50	
51	/** The status a person should see: a live request past its expiry is `expired` even before the monitor marks it. */
52	export function effectiveStatus(c: Pick<Confirmation, "status" | "expiresAt">, now: Timestamp): ConfirmationStatus {
53	  return LIVE_APPROVAL_STATUSES.includes(c.status) && c.expiresAt <= now ? "expired" : c.status;
54	}
55	
56	/** Labels for the status badges. */
57	export const APPROVAL_STATUS_LABELS: Record<ConfirmationStatus, string> = {
58	  pending: "Pending",
59	  approved: "Approved",
60	  rejected: "Declined",
61	  postponed: "Postponed",
62	  ignored: "Ignored",
63	  revoked: "Revoked",
64	  expired: "Expired",
65	  consumed: "Used",
66	  held: "Counting down",
67	};
68	
69	/** Which person actions apply to a request right now. */
70	export function allowedActions(c: Pick<Confirmation, "status" | "expiresAt">, now: Timestamp): ApprovalAction[] {
71	  switch (effectiveStatus(c, now)) {
72	    case "pending":
73	      return ["approve", "decline", "postpone", "ignore"];
74	    case "postponed":
75	      return ["approve", "decline", "postpone", "reopen", "revoke"];
76	    case "ignored":
77	      return ["reopen", "postpone", "decline"];
78	    case "approved":
79	      return ["revoke"];
80	    case "held":
81	      // A veto call (decision #102): approving is implicit (it runs when the countdown ends); the owner can only stop it.
82	      return ["deny"];
83	    default:
84	      return [];
85	  }
86	}
87	
88	export interface ApprovalContext {
89	  now: Timestamp;
90	  /** Who does it, e.g. `web:admin` or `system:approval-monitor`. */
91	  by: string;
92	  /** How long a request stays approvable once it is (back) to pending or approved from a postponement. */
93	  ttlMs: number;
94	  /** For `postpone`: what to wait for (already validated by the condition registry). */
95	  condition?: PostponeCondition;
96	  /** For `postpone` with a time: when it returns to pending. */
97	  until?: Timestamp;
98	  /** For `check`: short note on what the check saw. */
99	  note?: string;
100	}
101	
102	const addMs = (iso: Timestamp, ms: number) => new Date(Date.parse(iso) + ms).toISOString();
103	const minIso = (a: Timestamp, b: Timestamp) => (a < b ? a : b);
104	
105	/** The latest a postponed request can stay postponed: 7 days after it was asked. */
106	export const postponeDeadline = (c: Pick<Confirmation, "createdAt">): Timestamp => addMs(c.createdAt, MAX_POSTPONE_MS);
107	
108	/** A fresh use window (back to pending, or approved from a postponement), never past the request's life + one window. */
109	function freshWindow(c: Confirmation, ctx: ApprovalContext): Timestamp {
110	  return minIso(addMs(ctx.now, ctx.ttlMs), addMs(postponeDeadline(c), ctx.ttlMs));
111	}
112	
113	/** When the next reminder is due for a postponed request. */
114	export function remindAt(c: Pick<Confirmation, "postponed">): Timestamp | undefined {
115	  const p = c.postponed;
116	  if (!p) return undefined;
117	  return addMs(p.lastReminder ?? p.since, POSTPONE_REMIND_MS);
118	}
119	
120	/** True once a request has been postponed (this time) for 2 hours or more. */
121	export function reviewRequired(c: Pick<Confirmation, "status" | "postponed" | "expiresAt">, now: Timestamp): boolean {
122	  return effectiveStatus(c, now) === "postponed" && !!c.postponed && Date.parse(now) - Date.parse(c.postponed.since) >= POSTPONE_REVIEW_MS;
123	}
124	
125	function denied(message: string): never {
126	  throw new AxHubError("conflict", message);
127	}
128	
129	/**
130	 * Applies one person or monitor action and returns the new record (the input is not changed). Throws `conflict`
131	 * when the action doesn't apply to the request's current status, `validation` for a bad postponement.
132	 */
133	export function applyApprovalAction(c: Confirmation, action: ApprovalAction | ApprovalSystemAction, ctx: ApprovalContext): Confirmation {
134	  const now = ctx.now;
135	  const from = c.status;
136	  const status = effectiveStatus(c, now);
137	  const next: Confirmation = structuredClone(c);
138	  next.revision = (c.revision ?? 0) + 1;
139	  let note: string | undefined;
140	
141	  const person = (APPROVAL_ACTIONS as readonly string[]).includes(action);
142	  if (person && !allowedActions(c, now).includes(action as ApprovalAction)) {
143	    denied(status === "expired" ? "That request has expired." : `Can't ${action} a request that is ${APPROVAL_STATUS_LABELS[status].toLowerCase()}.`);
144	  }
145	
146	  switch (action) {
147	    case "approve":
148	      next.status = "approved";
149	      next.decidedAt = now;
150	      next.decidedBy = ctx.by;
151	      // From a postponement the use window starts now (the retry may be minutes away); from pending it is unchanged.
152	      if (from === "postponed") next.expiresAt = freshWindow(c, ctx);
153	      delete next.postponed;
154	      break;
155	    case "deny":
156	      next.status = "rejected";
157	      next.decidedAt = now;
158	      next.decidedBy = ctx.by;
159	      if (next.veto) next.veto.state = "denied";
160	      note = "veto denied";
161	      break;
162	    case "release":
163	      if (status !== "held" || !next.veto) denied("Only a held veto call can be released.");
164	      next.status = "approved";
165	      next.decidedAt = now;
166	      next.decidedBy = ctx.by;
167	      next.veto!.state = "running";
168	      next.veto!.startedAt = now;
169	      note = "countdown ended";
170	      break;
171	    case "lapse":
172	      if (from !== "held" || !next.veto) denied("Only a held veto call can lapse.");
173	      next.status = "expired";
174	      next.veto!.state = "expired";
175	      next.veto!.finishedAt = now;
176	      if (ctx.note !== undefined) next.veto!.note = ctx.note.slice(0, 300);
177	      note = ctx.note;
178	      break;
179	    case "decline":
180	      next.status = "rejected";
181	      next.decidedAt = now;
182	      next.decidedBy = ctx.by;
183	      delete next.postponed;
184	      break;
185	    case "ignore":
186	      next.status = "ignored";
187	      next.decidedAt = now;
188	      next.decidedBy = ctx.by;
189	      break;
190	    case "revoke":
191	      next.status = "revoked";
192	      next.decidedAt = now;
193	      next.decidedBy = ctx.by;
194	      delete next.postponed;
195	      break;
196	    case "reopen":
197	      next.status = "pending";
198	      next.expiresAt = freshWindow(c, ctx);
199	      delete next.decidedAt;
200	      delete next.decidedBy;
201	      delete next.postponed;
202	      break;
203	    case "postpone": {
204	      if (!ctx.condition) throw new AxHubError("validation", "Pick a time or a condition to wait for.");
205	      const deadline = postponeDeadline(c);
206	      if (deadline <= now) denied("That request is too old to postpone (7 days at most).");
207	      if (ctx.until !== undefined) {
208	        if (!(ctx.until > now)) throw new AxHubError("validation", "Pick a time in the future.");
209	        if (ctx.until > deadline) throw new AxHubError("validation", "That's past the 7-day limit for this request.");
210	      }
211	      next.status = "postponed";
212	      next.expiresAt = deadline;
213	      next.postponed = {
214	        condition: { kind: ctx.condition.kind, params: { ...ctx.condition.params } },
215	        since: now,
216	        firstSince: c.postponed?.firstSince ?? now,
217	        by: ctx.by,
218	        nextCheck: addMs(now, POSTPONE_CHECK_MS),
219	        reminders: 0,
220	      };
221	      next.decidedAt = now;
222	      next.decidedBy = ctx.by;
223	      note = ctx.condition.kind;
224	      break;
225	    }
226	    case "resume":
227	      if (status !== "postponed") denied("Only a postponed request can resume.");
228	      next.status = "pending";
229	      next.expiresAt = freshWindow(c, ctx);
230	      delete next.decidedAt;
231	      delete next.decidedBy;
232	      delete next.postponed;
233	      note = ctx.note;
234	      break;
235	    case "check":
236	    case "remind": {
237	      if (status !== "postponed" || !next.postponed) denied("Only a postponed request is checked or reminded.");
238	      const p = next.postponed;
239	      if (action === "check") {
240	        p.lastCheck = now;
241	        p.nextCheck = addMs(now, POSTPONE_CHECK_MS);
242	        if (ctx.note !== undefined) p.lastNote = ctx.note.slice(0, 300);
243	      } else {
244	        p.lastReminder = now;
245	        p.reminders += 1;
246	      }
247	      // Bookkeeping only: no history entry.
248	      return next;
249	    }
250	  }
251	  const entry = { at: now, by: ctx.by, from, to: next.status, ...(note ? { note: note.slice(0, 300) } : {}) };
252	  next.history = [...(c.history ?? []), entry].slice(-APPROVAL_HISTORY_MAX);
253	  return next;
254	}
