/**
 * Approval state machine (decision #90): the statuses an approval request moves through and who may move it.
 *
 *   pending   → approved | rejected (Declined) | postponed | ignored | expired
 *   postponed → pending (condition met, time reached, or Reopen) | approved | rejected | revoked | postponed (again) | expired
 *   ignored   → pending (Reopen) | rejected | postponed | expired
 *   approved  → consumed (Used, by the retry) | revoked | expired
 *   held      → rejected (Deny) | approved (Vinnie, when the countdown ends) | expired   (veto calls, decision #102)
 *   rejected, consumed, revoked, expired: final.
 *
 * Pure: every function takes the time it should use, so the monitor and the tests share one clock. Nothing here ever
 * changes what the approval is bound to (caller, tool, exact arguments, fingerprint, summary); only status, times and
 * the postponement record move. Storage applies a result with `replace` (compare-and-set on status + revision), so
 * two changes can never both win.
 */
import { AxHubError } from "./errors.js";
import type { Confirmation, ConfirmationStatus, PostponeCondition, Timestamp } from "./model.js";

const MIN = 60 * 1000;
const HOUR = 60 * MIN;
const DAY = 24 * HOUR;

/** A request lives at most this long from when it was asked: a postponement can't outlast it. */
export const MAX_POSTPONE_MS = 7 * DAY;
/** How often the monitor looks at a postponed request's condition. */
export const POSTPONE_CHECK_MS = 5 * MIN;
/** How often a postponed request reminds the owner. */
export const POSTPONE_REMIND_MS = 30 * MIN;
/** After this long postponed, the owner must review it (the console blocks until he does). */
export const POSTPONE_REVIEW_MS = 2 * HOUR;
/** History entries kept per request. */
export const APPROVAL_HISTORY_MAX = 30;

/** What a person can do from the approvals page. */
export type ApprovalAction = "approve" | "decline" | "postpone" | "ignore" | "revoke" | "reopen" | "deny";
export const APPROVAL_ACTIONS: readonly ApprovalAction[] = ["approve", "decline", "postpone", "ignore", "revoke", "reopen", "deny"];

/**
 * What the hub does by itself. The monitor never approves. `release` and `lapse` are Vinnie's (decision #102): a veto
 * call whose countdown ended runs (`release`, held → approved, used at once by the run) or, when the hub was down past
 * its time by more than a minute, expires (`lapse`).
 */
export type ApprovalSystemAction = "resume" | "check" | "remind" | "release" | "lapse";

/** Statuses that are over: nothing moves them again. */
export const FINAL_APPROVAL_STATUSES: readonly ConfirmationStatus[] = ["rejected", "consumed", "revoked", "expired"];

/** Statuses that time out at `expiresAt`. */
export const LIVE_APPROVAL_STATUSES: readonly ConfirmationStatus[] = ["pending", "approved", "postponed", "ignored", "held"];

/** The status a person should see: a live request past its expiry is `expired` even before the monitor marks it. */
export function effectiveStatus(c: Pick<Confirmation, "status" | "expiresAt">, now: Timestamp): ConfirmationStatus {
  return LIVE_APPROVAL_STATUSES.includes(c.status) && c.expiresAt <= now ? "expired" : c.status;
}

/** Labels for the status badges. */
export const APPROVAL_STATUS_LABELS: Record<ConfirmationStatus, string> = {
  pending: "Pending",
  approved: "Approved",
  rejected: "Declined",
  postponed: "Postponed",
  ignored: "Ignored",
  revoked: "Revoked",
  expired: "Expired",
  consumed: "Used",
  held: "Counting down",
};

/** Which person actions apply to a request right now. */
export function allowedActions(c: Pick<Confirmation, "status" | "expiresAt">, now: Timestamp): ApprovalAction[] {
  switch (effectiveStatus(c, now)) {
    case "pending":
      return ["approve", "decline", "postpone", "ignore"];
    case "postponed":
      return ["approve", "decline", "postpone", "reopen", "revoke"];
    case "ignored":
      return ["reopen", "postpone", "decline"];
    case "approved":
      return ["revoke"];
    case "held":
      // A veto call (decision #102): approving is implicit (it runs when the countdown ends); the owner can only stop it.
      return ["deny"];
    default:
      return [];
  }
}

export interface ApprovalContext {
  now: Timestamp;
  /** Who does it, e.g. `web:admin` or `system:approval-monitor`. */
  by: string;
  /** How long a request stays approvable once it is (back) to pending or approved from a postponement. */
  ttlMs: number;
  /** For `postpone`: what to wait for (already validated by the condition registry). */
  condition?: PostponeCondition;
  /** For `postpone` with a time: when it returns to pending. */
  until?: Timestamp;
  /** For `check`: short note on what the check saw. */
  note?: string;
}

const addMs = (iso: Timestamp, ms: number) => new Date(Date.parse(iso) + ms).toISOString();
const minIso = (a: Timestamp, b: Timestamp) => (a < b ? a : b);

/** The latest a postponed request can stay postponed: 7 days after it was asked. */
export const postponeDeadline = (c: Pick<Confirmation, "createdAt">): Timestamp => addMs(c.createdAt, MAX_POSTPONE_MS);

/** A fresh use window (back to pending, or approved from a postponement), never past the request's life + one window. */
function freshWindow(c: Confirmation, ctx: ApprovalContext): Timestamp {
  return minIso(addMs(ctx.now, ctx.ttlMs), addMs(postponeDeadline(c), ctx.ttlMs));
}

/** When the next reminder is due for a postponed request. */
export function remindAt(c: Pick<Confirmation, "postponed">): Timestamp | undefined {
  const p = c.postponed;
  if (!p) return undefined;
  return addMs(p.lastReminder ?? p.since, POSTPONE_REMIND_MS);
}

/** True once a request has been postponed (this time) for 2 hours or more. */
export function reviewRequired(c: Pick<Confirmation, "status" | "postponed" | "expiresAt">, now: Timestamp): boolean {
  return effectiveStatus(c, now) === "postponed" && !!c.postponed && Date.parse(now) - Date.parse(c.postponed.since) >= POSTPONE_REVIEW_MS;
}

function denied(message: string): never {
  throw new AxHubError("conflict", message);
}

/**
 * Applies one person or monitor action and returns the new record (the input is not changed). Throws `conflict`
 * when the action doesn't apply to the request's current status, `validation` for a bad postponement.
 */
export function applyApprovalAction(c: Confirmation, action: ApprovalAction | ApprovalSystemAction, ctx: ApprovalContext): Confirmation {
  const now = ctx.now;
  const from = c.status;
  const status = effectiveStatus(c, now);
  const next: Confirmation = structuredClone(c);
  next.revision = (c.revision ?? 0) + 1;
  let note: string | undefined;

  const person = (APPROVAL_ACTIONS as readonly string[]).includes(action);
  if (person && !allowedActions(c, now).includes(action as ApprovalAction)) {
    denied(status === "expired" ? "That request has expired." : `Can't ${action} a request that is ${APPROVAL_STATUS_LABELS[status].toLowerCase()}.`);
  }

  switch (action) {
    case "approve":
      next.status = "approved";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      // From a postponement the use window starts now (the retry may be minutes away); from pending it is unchanged.
      if (from === "postponed") next.expiresAt = freshWindow(c, ctx);
      delete next.postponed;
      break;
    case "deny":
      next.status = "rejected";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      if (next.veto) next.veto.state = "denied";
      note = "veto denied";
      break;
    case "release":
      if (status !== "held" || !next.veto) denied("Only a held veto call can be released.");
      next.status = "approved";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      next.veto!.state = "running";
      next.veto!.startedAt = now;
      note = "countdown ended";
      break;
    case "lapse":
      if (from !== "held" || !next.veto) denied("Only a held veto call can lapse.");
      next.status = "expired";
      next.veto!.state = "expired";
      next.veto!.finishedAt = now;
      if (ctx.note !== undefined) next.veto!.note = ctx.note.slice(0, 300);
      note = ctx.note;
      break;
    case "decline":
      next.status = "rejected";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      delete next.postponed;
      break;
    case "ignore":
      next.status = "ignored";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      break;
    case "revoke":
      next.status = "revoked";
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      delete next.postponed;
      break;
    case "reopen":
      next.status = "pending";
      next.expiresAt = freshWindow(c, ctx);
      delete next.decidedAt;
      delete next.decidedBy;
      delete next.postponed;
      break;
    case "postpone": {
      if (!ctx.condition) throw new AxHubError("validation", "Pick a time or a condition to wait for.");
      const deadline = postponeDeadline(c);
      if (deadline <= now) denied("That request is too old to postpone (7 days at most).");
      if (ctx.until !== undefined) {
        if (!(ctx.until > now)) throw new AxHubError("validation", "Pick a time in the future.");
        if (ctx.until > deadline) throw new AxHubError("validation", "That's past the 7-day limit for this request.");
      }
      next.status = "postponed";
      next.expiresAt = deadline;
      next.postponed = {
        condition: { kind: ctx.condition.kind, params: { ...ctx.condition.params } },
        since: now,
        firstSince: c.postponed?.firstSince ?? now,
        by: ctx.by,
        nextCheck: addMs(now, POSTPONE_CHECK_MS),
        reminders: 0,
      };
      next.decidedAt = now;
      next.decidedBy = ctx.by;
      note = ctx.condition.kind;
      break;
    }
    case "resume":
      if (status !== "postponed") denied("Only a postponed request can resume.");
      next.status = "pending";
      next.expiresAt = freshWindow(c, ctx);
      delete next.decidedAt;
      delete next.decidedBy;
      delete next.postponed;
      note = ctx.note;
      break;
    case "check":
    case "remind": {
      if (status !== "postponed" || !next.postponed) denied("Only a postponed request is checked or reminded.");
      const p = next.postponed;
      if (action === "check") {
        p.lastCheck = now;
        p.nextCheck = addMs(now, POSTPONE_CHECK_MS);
        if (ctx.note !== undefined) p.lastNote = ctx.note.slice(0, 300);
      } else {
        p.lastReminder = now;
        p.reminders += 1;
      }
      // Bookkeeping only: no history entry.
      return next;
    }
  }
  const entry = { at: now, by: ctx.by, from, to: next.status, ...(note ? { note: note.slice(0, 300) } : {}) };
  next.history = [...(c.history ?? []), entry].slice(-APPROVAL_HISTORY_MAX);
  return next;
}

