780	  // ─── Veto calls (decision #102) ─────────────────────────────────────────
781	
782	  private readonly vetoRuns = new Map<string, { abort: AbortController; done: Promise<void> }>();
783	
784	  /** Holds a veto call: stored whole with a countdown and a job, answered at once. Always throws `confirmation_required`. */
785	  private async holdVeto(
786	    call: Call,
787	    confirmation: Confirmation,
788	    service: Service,
789	    tool: Tool,
790	    ctx: { call: Call; service: Service; tool: Tool; policy: "confirm" },
791	  ): Promise<never> {
792	    const now = this.nowIso();
793	    const { vetoSeconds, vetoWarningSeconds } = vetoSettingsFor(service, tool.name);
794	    const runsAt = this.nowIso(vetoSeconds * 1000);
795	    const jobId = randomUUID();
796	    confirmation.status = "held";
797	    // Never run late by more than a minute: past this it can only expire.
798	    confirmation.expiresAt = new Date(Date.parse(runsAt) + VETO_MAX_LATE_MS).toISOString();
799	    confirmation.held = { arguments: call.arguments, caller: call.caller, jobId };
800	    if (call.timeoutMs) confirmation.held.timeoutMs = call.timeoutMs;
801	    confirmation.veto = { seconds: vetoSeconds, warningSeconds: vetoWarningSeconds, runsAt, state: "held" };
802	    await this.storage.confirmations.save(confirmation);
803	    await this.storage.jobs.save({
804	      schemaVersion: SCHEMA_VERSION,
805	      id: jobId,
806	      callId: call.id,
807	      correlationId: call.correlationId,
808	      callerId: call.caller.id,
809	      target: { ...call.target },
810	      state: "awaiting_confirmation",
811	      progress: { current: 0, message: `Veto countdown: axHub runs it at ${runsAt} unless the owner denies it.` },
812	      createdAt: now,
813	      updatedAt: now,
814	      confirmationId: confirmation.id,
815	    });
816	    this.events.emit({ type: "confirmation", confirmationId: confirmation.id, status: "held", correlationId: call.correlationId });
817	    this.observe({ kind: "requested", confirmation, ...ctx });
818	    await this.audit("confirmation_requested", "confirmation_required", call, { note: `veto ${confirmation.id} (job ${jobId}, runs ${runsAt})` });
819	    throw new AxHubError(
820	      "confirmation_required",
821	      `${qualified(call)} is on a ${vetoSeconds} s veto countdown: axHub runs it by itself at ${runsAt} unless the owner denies it. Don't call it again; read the result later with get_job("${jobId}").`,
822	      {
823	        details: {
824	          confirmationId: confirmation.id,
825	          summary: confirmation.summary,
826	          expiresAt: confirmation.expiresAt,
827	          held: true,
828	          veto: true,
829	          jobId,
830	          runsAt,
831	          secondsLeft: vetoSeconds,
832	          countdownSeconds: vetoSeconds,
833	          warningSeconds: vetoWarningSeconds,
834	        },
