// ─── Veto calls (decision #102) ─────────────────────────────────────────

private readonly vetoRuns = new Map<string, { abort: AbortController; done: Promise<void> }>();

/** Holds a veto call: stored whole with a countdown and a job, answered at once. Always throws `confirmation_required`. */
private async holdVeto(
  call: Call,
  confirmation: Confirmation,
  service: Service,
  tool: Tool,
  ctx: { call: Call; service: Service; tool: Tool; policy: "confirm" },
): Promise<never> {
  const now = this.nowIso();
  const { vetoSeconds, vetoWarningSeconds } = vetoSettingsFor(service, tool.name);
  const runsAt = this.nowIso(vetoSeconds * 1000);
  const jobId = randomUUID();
  confirmation.status = "held";
  // Never run late by more than a minute: past this it can only expire.
  confirmation.expiresAt = new Date(Date.parse(runsAt) + VETO_MAX_LATE_MS).toISOString();
  confirmation.held = { arguments: call.arguments, caller: call.caller, jobId };
  if (call.timeoutMs) confirmation.held.timeoutMs = call.timeoutMs;
  confirmation.veto = { seconds: vetoSeconds, warningSeconds: vetoWarningSeconds, runsAt, state: "held" };
  await this.storage.confirmations.save(confirmation);
  await this.storage.jobs.save({
    schemaVersion: SCHEMA_VERSION,
    id: jobId,
    callId: call.id,
    correlationId: call.correlationId,
    callerId: call.caller.id,
    target: { ...call.target },
    state: "awaiting_confirmation",
    progress: { current: 0, message: `Veto countdown: axHub runs it at ${runsAt} unless the owner denies it.` },
    createdAt: now,
    updatedAt: now,
    confirmationId: confirmation.id,
  });
  this.events.emit({ type: "confirmation", confirmationId: confirmation.id, status: "held", correlationId: call.correlationId });
  this.observe({ kind: "requested", confirmation, ...ctx });
  await this.audit("confirmation_requested", "confirmation_required", call, { note: `veto ${confirmation.id} (job ${jobId}, runs ${runsAt})` });
  throw new AxHubError(
    "confirmation_required",
    `${qualified(call)} is on a ${vetoSeconds} s veto countdown: axHub runs it by itself at ${runsAt} unless the owner denies it. Don't call it again; read the result later with get_job("${jobId}").`,
    {
      details: {
        confirmationId: confirmation.id,
        summary: confirmation.summary,
        expiresAt: confirmation.expiresAt,
        held: true,
        veto: true,
        jobId,
        runsAt,
        secondsLeft: vetoSeconds,
        countdownSeconds: vetoSeconds,
        warningSeconds: vetoWarningSeconds,
      },
    },
  );
}

/** Veto calls still counting down (for Vinnie's countdown and warnings). */
async listHeldVetoes(): Promise<Confirmation[]> {
  const now = this.nowIso();
  return (await this.storage.confirmations.list({ now, statuses: ["held"], limit: 200 })).filter((c) => c.veto && c.held);
}

/** A veto call's run, while it runs in this process (so a stream can tell running from stale). */
vetoRunning(jobId: string): boolean {
  return this.vetoRuns.has(jobId);
}

/**
 * Vinnie's pass (decision #102): runs veto calls whose countdown ended (at most a minute late; later they expire),
 * closes the jobs of denied or expired ones. Returns at once with the runs it started, so a long command never
 * blocks the next pass. Safe to call every second and concurrently.
 */
async settleVetoes(hooks: VetoHooks = {}): Promise<{ settled: number; runs: Promise<void>[] }> {
  const waiting = await this.storage.jobs.listByState(["awaiting_confirmation"], 200);
  let settled = 0;
  const runs: Promise<void>[] = [];
  for (const job of waiting) {
    if (!job.confirmationId || this.vetoRuns.has(job.id) || this.heldRunning.has(job.id)) continue;
    this.heldRunning.add(job.id);
    try {
      const c = await this.storage.confirmations.get(job.confirmationId);
      if (!c?.veto) continue; // a #101 held call
      const out = await this.settleVeto(job, c, hooks);
      if (out === true) settled += 1;
      else if (out) {
        settled += 1;
        runs.push(out.run);
      }
    } catch (err) {
      this.log.warn("veto call could not be settled", { jobId: job.id, error: err instanceof Error ? err.message : String(err) });
    } finally {
      this.heldRunning.delete(job.id);
    }
  }
  return { settled, runs };
}

private vetoHook(hooks: VetoHooks, change: VetoStateChange): void {
  try {
    hooks.onState?.(change);
  } catch {
    // a broken listener must not break the run
  }
}

/** Closes a held job that is still waiting. False when something else closed it first. */
private async closeHeldJob(jobId: string, state: Job["state"], result: Result): Promise<boolean> {
  const fresh = await this.storage.jobs.get(jobId);
  if (!fresh || fresh.state !== "awaiting_confirmation") return false;
  const { progress: _done, ...rest } = fresh;
  await this.storage.jobs.save({ ...rest, state, updatedAt: this.nowIso(), result: { ...this.storable(result), jobId } });
  this.events.emit({ type: "job_state", jobId, state, correlationId: fresh.correlationId });
  return true;
}

/** Records a veto state on the confirmation (compare-and-set, one retry). */
private async setVeto(id: string, patch: Partial<NonNullable<Confirmation["veto"]>>): Promise<Confirmation | undefined> {
  for (let i = 0; i < 3; i++) {
    const c = await this.storage.confirmations.get(id);
    if (!c?.veto) return undefined;
    const next: Confirmation = structuredClone(c);
    next.veto = { ...c.veto, ...patch };
    next.revision = (c.revision ?? 0) + 1;
    if (await this.storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 })) return next;
  }
  return undefined;
}

/** A started run is wrapped (`{ run }`), so awaiting this never waits for the command itself. */
private async settleVeto(job: Job, c: Confirmation, hooks: VetoHooks): Promise<boolean | { run: Promise<void> } | undefined> {
  const now = this.nowIso();
  const ids = { id: job.callId, correlationId: job.correlationId };
  const drop = async (state: VetoState, why: string, code: "denied" | "cancelled" = "denied") => {
    if (!(await this.closeHeldJob(job.id, "cancelled", errorResult(ids, new AxHubError(code, why))))) return false;
    const recorded = c.veto?.state === state ? c : await this.setVeto(c.id, { state, finishedAt: c.veto?.finishedAt ?? now });
    this.vetoHook(hooks, { confirmationId: c.id, jobId: job.id, state, confirmation: recorded ?? c });
    return true;
  };
  if (!c.held || c.held.jobId !== job.id || c.callerId !== job.callerId) return drop("failed", "The veto request for this held call is gone.");
  const veto = c.veto!;
  const late = Date.parse(now) - Date.parse(veto.runsAt);
  switch (c.status) {
    case "held": {
      if (late < 0) return undefined;
      if (late > VETO_MAX_LATE_MS) {
        const note = `axHub was down when it was due; ${Math.round(late / 1000)} s late, so it did not run`;
        const next = applyApprovalAction(c, "lapse", { now, by: VINNIE_BY, ttlMs: 0, note });
        if (!(await this.storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 }))) return undefined;
        this.log.warn("veto call expired: the hub was down past its time", { confirmationId: c.id, lateSeconds: Math.round(late / 1000) });
        await this.audit("confirmation_decided", "denied", undefined, { target: c.target, note: `veto ${c.id} expired (${Math.round(late / 1000)} s late)`, callerId: VINNIE_BY, via: "hub" });
        await this.closeHeldJob(job.id, "cancelled", errorResult(ids, new AxHubError("denied", "The veto countdown ended while axHub was down, so axHub did not run it (it never runs more than a minute late).")));
        this.vetoHook(hooks, { confirmationId: c.id, jobId: job.id, state: "expired", confirmation: next });
        return true;
      }
      let next: Confirmation;
      try {
        next = applyApprovalAction(c, "release", { now, by: VINNIE_BY, ttlMs: 0 });
      } catch {
        return undefined;
      }
      // Compare-and-set: a Deny that landed first wins, and the next pass closes the job.
      if (!(await this.storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 }))) return undefined;
      await this.audit("confirmation_decided", "ok", undefined, { target: c.target, note: `veto ${c.id} countdown ended; running (job ${job.id})`, callerId: VINNIE_BY, via: "hub" });
      return { run: this.startVetoRun(job, next, hooks) };
    }
    case "approved":
      // Released, but the run never started (restart in between): run it if still within the minute, else expire.
      if (late <= VETO_MAX_LATE_MS && c.expiresAt > now) return { run: this.startVetoRun(job, c, hooks) };
      return drop("expired", "The veto countdown ended while axHub was down, so axHub did not run it.");
    case "rejected":
      return drop("denied", "The owner denied this call before its countdown ended, so axHub did not run it.");
    case "expired":
      return drop("expired", "The veto countdown ended while axHub was down, so axHub did not run it.");
    default:
      return drop("failed", "This veto call can no longer run.");
  }
}

private startVetoRun(job: Job, c: Confirmation, hooks: VetoHooks): Promise<void> {
  const abort = new AbortController();
  const entry = { abort, done: Promise.resolve() };
  this.vetoRuns.set(job.id, entry);
  entry.done = this.runVeto(job, c, hooks, abort.signal)
    .catch((err) => this.log.warn("veto run failed", { jobId: job.id, error: err instanceof Error ? err.message : String(err) }))
    .finally(() => this.vetoRuns.delete(job.id));
  return entry.done;
}

private async runVeto(job: Job, c: Confirmation, hooks: VetoHooks, signal: AbortSignal): Promise<void> {
  const held = c.held!;
  const started = this.nowIso();
  const waiting = await this.storage.jobs.get(job.id);
  if (!waiting || waiting.state !== "awaiting_confirmation") return;
  await this.storage.jobs.save({ ...waiting, state: "running", progress: { current: 0, message: "The veto countdown ended: axHub is running it." }, updatedAt: started });
  this.events.emit({ type: "job_state", jobId: job.id, state: "running", correlationId: job.correlationId });
  this.vetoHook(hooks, { confirmationId: c.id, jobId: job.id, state: "running", confirmation: c });
  const result = await this.call(
    {
      schemaVersion: SCHEMA_VERSION,
      id: job.callId,
      correlationId: job.correlationId,
      caller: held.caller,
      target: { ...c.target },
      arguments: held.arguments,
      requestedAt: started,
      confirmationId: c.id,
      ...(held.timeoutMs ? { timeoutMs: held.timeoutMs } : {}),
    },
    {
      waitToEnd: true,
      signal,
      onOutput: (chunk) => {
        try {
          hooks.onOutput?.({ ...chunk, jobId: job.id });
        } catch {
          // a broken listener must not break the run
        }
      },
    },
  );
  const s = result.structured;
  const exitCode =
    s && typeof s === "object" && !Array.isArray(s) && Object.hasOwn(s, "exitCode") && (typeof s.exitCode === "number" || s.exitCode === null)
      ? (s.exitCode as number | null)
      : undefined;
  const vetoState: VetoState = result.status === "ok" && !(typeof exitCode === "number" && exitCode !== 0) ? "ran" : "failed";
  const jobState: Job["state"] = result.status === "ok" ? "succeeded" : result.error?.code === "cancelled" ? "cancelled" : "failed";
  const running = await this.storage.jobs.get(job.id);
  if (running) {
    const { progress: _done, ...rest } = running;
    await this.storage.jobs.save({ ...rest, state: jobState, updatedAt: this.nowIso(), result: { ...this.storable(result), jobId: job.id } });
    this.events.emit({ type: "job_state", jobId: job.id, state: jobState, correlationId: job.correlationId });
  }
  const patch: Partial<NonNullable<Confirmation["veto"]>> = { state: vetoState, finishedAt: this.nowIso() };
  if (exitCode !== undefined) patch.exitCode = exitCode;
  if (result.status === "error" && result.error) patch.note = truncate(result.error.message, 300);
  const recorded = await this.setVeto(c.id, patch);
  this.vetoHook(hooks, { confirmationId: c.id, jobId: job.id, state: vetoState, ...(exitCode !== undefined ? { exitCode } : {}), confirmation: recorded ?? c });
}

