  approved: { label: "Approved", statuses: ["approved"] },
  declined: { label: "Declined", statuses: ["rejected"] },
  ignored: { label: "Ignored", statuses: ["ignored"] },
  revoked: { label: "Revoked", statuses: ["revoked"] },
  used: { label: "Used", statuses: ["consumed"] },
  expired: { label: "Expired", statuses: ["expired"] },
};

const ID_RE = /^[0-9a-f-]{36}$/;
const ACTION_LABELS: Record<ApprovalAction, string> = {
  approve: "Approve",
  decline: "Decline",
  postpone: "Postpone",
  ignore: "Ignore",
  revoke: "Revoke",
  reopen: "Reopen",
  deny: "Deny",
};
const OK_KEYS: Record<ApprovalAction, string> = {
  approve: "approved",
  decline: "rejected",
  postpone: "postponed",
  ignore: "ignored",
  revoke: "revoked",
  reopen: "reopened",
  deny: "denied",
};
/** Postpone presets in minutes. */
const PRESETS: [number, string][] = [[15, "15 minutes"], [30, "30 minutes"], [60, "1 hour"], [120, "2 hours"], [240, "4 hours"], [480, "8 hours"], [1440, "1 day"], [2880, "2 days"]];
const UNITS: Record<string, number> = { minutes: 60_000, hours: 3_600_000, days: 86_400_000 };

function statusOf(c: Confirmation, now: string): ConfirmationStatus {
  return effectiveStatus(c, now);
}

/** The arguments part of the stored summary (`<tool> with arguments <json>`), the whole summary otherwise. */
function argsLine(c: Confirmation): string {
  const marker = " with arguments ";
  const i = c.summary.indexOf(marker);
  return i >= 0 ? c.summary.slice(i + marker.length) : c.summary;
}


/** Printable ASCII and new lines only; anything else is written out as a \\u escape so nothing can hide in the code. */
const codeSafe = (text: string) => text.replace(/[^\x20-\x7e\n]/g, (ch) => `\\u${ch.charCodeAt(0).toString(16).padStart(4, "0")}`);

/**
 * The approval in three layers (decision #99): what is being approved (the caller's title, else one built from the
 * tool), what it does (the caller's description + the tool's own description and effect), and the exact code that runs.
 */
/** Where a veto call is (decision #102), from what storage holds: the status wins over a stale recorded state. */
export function vetoStateOf(c: Confirmation, now: string): VetoState {
  const v = c.veto;
  if (!v) return "failed";
  if (c.status === "held") return effectiveStatus(c, now) === "expired" ? "expired" : "held";
  if (c.status === "rejected") return "denied";
  if (c.status === "expired" && v.state !== "ran" && v.state !== "failed") return "expired";
  return v.state === "held" ? "running" : v.state;
}

/** Seconds until a veto call runs (0 once due). */
export function vetoSecondsLeft(c: Confirmation, now: string): number {
  if (!c.veto) return 0;
  return Math.max(0, Math.ceil((Date.parse(c.veto.runsAt) - Date.parse(now)) / 1000));
}

/** The veto object the approval page, the feeds and the banner show (veto@1). */
export function vetoView(c: Confirmation, now: string) {
  const v = c.veto!;
  const state = vetoStateOf(c, now);
  return {
    state,
    runsAt: v.runsAt,
    secondsLeft: state === "held" ? vetoSecondsLeft(c, now) : 0,
    countdownSeconds: v.seconds,
    warningSeconds: v.warningSeconds,
    ...(v.startedAt ? { startedAt: v.startedAt } : {}),
    ...(v.finishedAt ? { finishedAt: v.finishedAt } : {}),
    ...(v.exitCode !== undefined ? { exitCode: v.exitCode } : {}),
    ...(v.note ? { note: displaySafe(v.note) } : {}),
  };
}

/** The links a veto item carries (relative to the hub): Deny and the job's live stream. */
export function vetoLinks(c: Confirmation) {
  const jobId = c.held?.jobId;
  return {
    ...(jobId ? { jobId } : {}),
    denyUrl: `/auth/api/approvals/${c.id}/deny`,
    ...(jobId ? { streamUrl: `/auth/api/jobs/${jobId}/stream` } : {}),
  };
}

export function approvalExplain(c: Confirmation, now: string = new Date().toISOString()) {
  const qualified = displaySafe(`${c.target.service}.${c.target.tool}`);
  const raw = argsLine(c);
  let args: unknown;
  try {
    args = JSON.parse(raw);
  } catch {
    args = undefined;
  }
  const pretty = args === undefined ? raw : codeSafe(JSON.stringify(args, null, 2));
  const command = args && typeof args === "object" && !Array.isArray(args) && typeof (args as Record<string, unknown>).command === "string"
    ? codeSafe(String((args as Record<string, unknown>).command))
    : undefined;
  const effect = c.tool?.destructive ? "destructive" : c.tool?.readOnly ? "read-only" : "changes";
  return {
    // Veto calls (decision #102): the page shows a countdown and Deny on the first screen, no Approve.
    ...(c.veto ? { veto: vetoView(c, now), ...(effectiveStatus(c, now) === "held" ? { status: "held" as const } : {}) } : {}),
    title: c.reason?.title ?? `Run ${qualified}`,
    reasonGiven: !!c.reason,
    ...(c.reason ? { description: c.reason.description } : {}),
    ...(c.tool?.description ? { toolDescription: c.tool.description } : {}),
    effect,
    code: {
      service: displaySafe(c.target.service),
      tool: displaySafe(c.target.tool),
      qualified,
      arguments: pretty,
      ...(command !== undefined ? { command } : {}),
    },
  };
}

/** One request as the AXHub web app shows it. Every string is display-safe; the app escapes on render. */
export function approvalView(c: Confirmation, now: string, conditions: ConditionRegistry) {
  const s = statusOf(c, now);
  const p = c.postponed;
  const postponed = p && s === "postponed"
    ? {
        kind: p.condition.kind,
        waitingFor: displaySafe(conditions.describe(p.condition)),
        ...(p.condition.kind === "time" && p.condition.params.until ? { until: p.condition.params.until } : {}),
        since: p.since,
        ...(p.lastCheck ? { lastCheck: p.lastCheck } : {}),
        ...(p.lastNote ? { lastNote: displaySafe(p.lastNote) } : {}),
        ...(remindAt(c) ? { nextReminder: remindAt(c) } : {}),
        reminders: p.reminders,
      }
    : undefined;
  return {
    id: c.id,
    tool: displaySafe(`${c.target.service}.${c.target.tool}`),
    summary: c.summary,
    args: argsLine(c),
    ...approvalExplain(c, now),
    ...(c.veto ? vetoLinks(c) : {}),
    /** The summary fits on one line, so a collapsed row shows the complete call and may carry Approve. */
    whole: c.summary.length <= ONE_LINE_MAX && !/[\r\n]/.test(c.summary),
    status: s,
    statusLabel: APPROVAL_STATUS_LABELS[s],
    reviewRequired: reviewRequired(c, now),
    actions: allowedActions(c, now),
    revision: c.revision ?? 0,
    callerId: displaySafe(c.callerId),
    createdAt: c.createdAt,
    expiresAt: c.expiresAt,
    showExpires: s === "pending" || s === "approved" || s === "ignored",
    ...(s === "held" ? { statusLabel: APPROVAL_STATUS_LABELS.held } : {}),
    ...(c.decidedBy && s !== "pending" ? { decidedBy: displaySafe(c.decidedBy) } : {}),
    ...(postponed ? { postponed } : {}),
    history: (c.history ?? []).slice().reverse().map((h) => ({
      at: h.at,
      from: APPROVAL_STATUS_LABELS[h.from],
      to: APPROVAL_STATUS_LABELS[h.to],
      by: displaySafe(h.by),
      ...(h.note ? { note: displaySafe(h.note) } : {}),
    })),
  };
}

export function registerApprovalRoutes(r: Router, d: ApprovalsWebDeps): void {
  const { storage } = d;
  const json = express.json({ limit: "16kb" });
  const nowIso = () => (d.now ? d.now() : new Date()).toISOString();
  const ctx = (): ConditionContext => ({ ...(d.conditionContext ?? {}), now: () => (d.now ? d.now() : new Date()) });
  const view = (c: Confirmation, now: string) => approvalView(c, now, d.conditions);
  const fail = (res: Response, status: number, code: string, message: string) => res.status(status).json({ error: { code, message } });
  const autoState = () => {
    const w = d.approvalLog?.activeWindow();
    return {
      available: !!d.approvalLog,
      minutes: [...AUTO_APPROVE_MINUTES],
      ...(w ? { window: { id: w.id, until: w.until, minutes: w.minutes, by: displaySafe(w.by), approvedCount: w.approvedCount } } : {}),
    };
  };

  /** Veto calls still counting down (decision #102), soonest first. */
  const heldVetoes = async (now: string) =>
    (await storage.confirmations.list({ now, statuses: ["held"], limit: 100 }))
      .filter((c) => c.veto && statusOf(c, now) === "held")
      .sort((a, b) => a.veto!.runsAt.localeCompare(b.veto!.runsAt));
  const commandOf = (c: Confirmation) => {
    const cmd = approvalExplain(c).code.command;
    return cmd !== undefined ? { command: cmd.length > 300 ? `${cmd.slice(0, 300)}…` : cmd } : {};
  };

  // ─── feed for banners (decision #85; postponed + reminders by decision #95) ───
  r.get("/auth/admin/approvals.json", async (req, res) => {
    const origin = req.header("origin");
    res.set("Cache-Control", "no-store");
    res.set("Vary", "Origin, Cookie");
    if (origin && origin.toLowerCase() !== d.hubOrigin(req).toLowerCase()) {
      if (!d.feedOriginOk(origin)) return res.status(403).json({ error: { code: "denied", message: "Not allowed from this site." } });
      res.set("Access-Control-Allow-Origin", origin);
      res.set("Access-Control-Allow-Credentials", "true");
    }
    const who = await d.current(req);
    if (!who) return res.status(401).json({ signedIn: false, approvalsUrl: `${d.hubOrigin(req)}/auth/admin/approvals` });
    if (who.user.mustChangePassword || who.user.role !== "admin") return res.status(403).json({ signedIn: true, admin: false });
    const now = nowIso();
    const pendingOnly = await storage.confirmations.listPending(now);
    const held = await heldVetoes(now);
    const pending = [...held, ...pendingOnly];
    const postponed = (await storage.confirmations.list({ now, statuses: ["postponed"], limit: 100 })).filter((c) => statusOf(c, now) === "postponed");
    const base = `${d.hubOrigin(req)}/auth/admin/approvals`;
    const item = (c: Confirmation) => ({
      id: c.id,
      tool: displaySafe(`${c.target.service}.${c.target.tool}`),
      title: approvalExplain(c, now).title,
      summary: c.summary.length > 300 ? `${c.summary.slice(0, 300)}…` : c.summary,
      createdAt: c.createdAt,
      expiresAt: c.expiresAt,
      url: `${base}/${c.id}`,
      status: statusOf(c, now),
      ...(c.veto ? { veto: vetoView(c, now), ...vetoLinks(c), ...commandOf(c) } : {}),
    });
    res.json({
      signedIn: true,
      admin: true,
      // `count` and `pending` are what's waiting on the owner: pending requests, plus veto calls counting down
      // (decision #102: `status: "held"`, `veto`, `denyUrl`, `streamUrl`, `jobId`), held first.
      count: pending.length,
      approvalsUrl: base,
      pending: pending.slice(0, 20).map(item),
      heldCount: held.length,
      held: held.slice(0, 20).map(item),
      postponedCount: postponed.length,
      reviewCount: postponed.filter((c) => reviewRequired(c, now)).length,
      postponed: postponed.slice(0, 20).map((c) => {
        const p = c.postponed!;
        const until = p.condition.kind === "time" ? p.condition.params.until : undefined;
        return {
          ...item(c),
          postponed: {
            kind: p.condition.kind,
            waitingFor: displaySafe(d.conditions.describe(p.condition)),
            ...(until ? { until } : {}),
            since: p.since,
            firstSince: p.firstSince,
            nextCheck: p.nextCheck,
            ...(p.lastCheck ? { lastCheck: p.lastCheck } : {}),
            ...(p.lastReminder ? { lastReminder: p.lastReminder } : {}),
            remindAt: remindAt(c),
            reminders: p.reminders,
          },
          reviewRequired: reviewRequired(c, now),
        };
      }),
    });
  });

  // ─── the old pages: every one now lives in the AXHub web app ──────────────
  // Links people already have (Claude's "approve here", banners, alerts, the phone) keep working: same paths, they
  // land on the same request in the new pages.
  r.get("/auth/admin/approvals", (req, res) => {
    const status = typeof req.query.status === "string" && Object.prototype.hasOwnProperty.call(APPROVAL_FILTERS, req.query.status) ? req.query.status : "";
    d.toWebApp(req, res, status && status !== "all" ? `approvals?status=${status}` : "approvals");
  });
  r.get("/auth/admin/approvals/log", (req, res) => d.toWebApp(req, res, "approvals/log"));
  r.get(["/auth/admin/approvals/:id", "/auth/admin/approvals/:id/postpone"], (req, res, next) => {
    const id = String(req.params.id);
    if (!ID_RE.test(id)) return next();
    d.toWebApp(req, res, `approvals/${id}`);
  });

  // ─── the grid ───────────────────────────────────────────────────────────
  r.get("/auth/api/approvals", d.api(true), async (req, res) => {
    const now = nowIso();
    const filter = typeof req.query.status === "string" && Object.prototype.hasOwnProperty.call(APPROVAL_FILTERS, req.query.status) ? req.query.status : "all";
    const pageNo = Math.min(10_000, Math.max(1, Number.parseInt(String(req.query.page ?? "1"), 10) || 1));
    const statuses = APPROVAL_FILTERS[filter]!.statuses;
    const total = await storage.confirmations.count(statuses ? { now, statuses } : { now });
    const items = await storage.confirmations.list({ now, ...(statuses ? { statuses } : {}), limit: APPROVALS_PAGE_SIZE, offset: (pageNo - 1) * APPROVALS_PAGE_SIZE });
    const pendingNow = await storage.confirmations.listPending(now);
    const waiting = pendingNow.length;
    const postponed = await storage.confirmations.count({ now, statuses: ["postponed"] });
    const held = await heldVetoes(now);
    res.json({
      // What waits on the owner (decision #102): veto calls counting down first, then pending requests.
      pending: [...held, ...pendingNow].slice(0, 20).map((c) => view(c, now)),
