    if (!c) return fail(res, 404, "not_found", d.messages.noSuch!);
    res.json({ item: view(c, nowIso()), auto: autoState() });
  });

  /** What Postpone offers for one request: presets that fit before it gives up, the custom units, the conditions. */
  r.get("/auth/api/approvals/:id/postpone", d.api(true), async (req, res) => {
    const id = String(req.params.id);
    const c = ID_RE.test(id) ? await storage.confirmations.get(id) : undefined;
