      presets: PRESETS.filter(([m]) => m <= maxMin).map(([minutes, label]) => ({ minutes, label })),
      units: Object.keys(UNITS),
      conditions: d.conditions.list().filter((k) => k.kind !== "time").map((k) => ({ kind: k.kind, label: k.label, built: k.built, params: k.params.map((p) => ({ name: p.name, label: p.label, ...(p.placeholder ? { placeholder: p.placeholder } : {}) })) })),
    });
  });

  // ─── Deny a veto call (decision #102, veto@1) ─────────────────────────────
  // Same rules as every action below; there is no approve for a veto call (it runs by itself when the countdown ends).
