76	/** The push for one phase. Pure, so tests pin exactly what leaves the hub. */
77	export function vetoPushPayload(c: Confirmation, phase: VetoPushPhase, now: string, opts: { publicUrl?: string; includeCommand?: boolean } = {}): VetoPushPayload {
