98	/** Where Vinnie's pushes go. */
99	export interface VetoPushSender {
100	  send(payload: VetoPushPayload): Promise<boolean>;
101	}
102	
103	/**
104	 * ntfy (the owner's existing push topic, AXHUB_PUSH_NTFY_*): the message body is the JSON payload for the AmberX app;
105	 * title, tags and the tap action are readable in any ntfy client. Same transport rules as approval pushes: https,
106	 * no redirects, short timeout, bounded rate; a failed push is logged and dropped, the call's countdown is unaffected.
107	 */
108	export function ntfyVetoSender(config: ApprovalPushConfig, deps: { log: Pick<Logger, "info" | "warn">; fetchImpl?: typeof fetch; timeoutMs?: number; maxPerWindow?: number; windowMs?: number }): VetoPushSender {
109	  const sent: number[] = [];
110	  return {
111	    async send(p) {
112	      try {
113	        const t = Date.now();
114	        const windowMs = deps.windowMs ?? 10 * 60_000;
115	        while (sent.length && t - sent[0]! > windowMs) sent.shift();
116	        if (sent.length >= (deps.maxPerWindow ?? 60)) {
117	          deps.log.warn("vinnie: push skipped, too many in a short time");
118	          return false;
119	        }
120	        sent.push(t);
121	        const mins = Math.floor(p.secondsLeft / 60);
122	        const left = `${mins}:${String(p.secondsLeft % 60).padStart(2, "0")}`;
123	        const title =
124	          p.phase === "held" ? `axHub: runs in ${left} unless you deny it` : p.phase === "warning" ? `axHub: ${p.secondsLeft} s left to deny` : "axHub: running now";
125	        const headers: Record<string, string> = { "content-type": "application/json" };
126	        if (config.token) headers.authorization = `Bearer ${config.token}`;
127	        const body: Record<string, unknown> = {
128	          topic: config.topic,
129	          title,
130	          message: JSON.stringify(p),
131	          priority: p.phase === "running" ? 4 : 5,
132	          tags: ["veto", p.phase],
133	        };
134	        if (/^https:\/\//.test(p.approvalUrl)) {
135	          body.click = p.approvalUrl;
136	          if (p.phase !== "running") body.actions = [{ action: "view", label: "Deny", url: p.approvalUrl, clear: true }];
137	        }
138	        const res = await (deps.fetchImpl ?? fetch)(config.url, { method: "POST", headers, body: JSON.stringify(body), redirect: "manual", signal: AbortSignal.timeout(deps.timeoutMs ?? 8000) });
139	        if (res.status >= 200 && res.status < 300) return true;
140	        deps.log.warn("vinnie: push refused by the push server", { status: res.status });
141	        return false;
142	      } catch (err) {
143	        deps.log.warn("vinnie: push failed", { errorName: err instanceof Error ? err.name : typeof err });
144	        return false;
145	      }
146	    },
147	  };
148	}
