165	export class Vinnie {
166	  private readonly jobs = new Map<string, JobRecord>();
167	  private timer: NodeJS.Timeout | undefined;
168	  private busy = false;
169	  private readonly running = new Set<Promise<void>>();
170	  /** Which phases were pushed per confirmation (in memory: after a restart a warning may repeat, never the reverse). */
171	  private readonly pushed = new Map<string, Set<VetoPushPhase>>();
172	  private unsubscribe: (() => void) | undefined;
173	  private readonly pushes = new Set<Promise<boolean>>();
174	
175	  constructor(private readonly deps: VinnieDeps) {}
176	
177	  /** Sends one phase once per call. Never throws; never blocks the countdown. */
178	  protected notify(c: Confirmation, phase: VetoPushPhase): void {
179	    const push = this.deps.push;
180	    if (!push || !c.veto || !c.held) return;
181	    let phases = this.pushed.get(c.id);
182	    if (!phases) this.pushed.set(c.id, (phases = new Set()));
183	    if (phases.has(phase)) return;
184	    phases.add(phase);
185	    const payload = vetoPushPayload(c, phase, this.nowIso(), { ...(this.deps.publicUrl ? { publicUrl: this.deps.publicUrl } : {}), includeCommand: this.deps.pushCommand !== false });
186	    const p = push.send(payload).catch(() => false);
187	    this.pushes.add(p);
188	    void p.finally(() => this.pushes.delete(p));
189	  }
190	
191	  private nowIso(): string {
192	    return (this.deps.now ? this.deps.now() : new Date()).toISOString();
193	  }
194	
195	  start(): void {
196	    if (this.timer) return;
197	    this.listen();
198	    this.timer = setInterval(() => {
199	      if (this.busy) return;
200	      void this.tick().catch((err) => this.deps.log.warn("vinnie: tick failed", { error: err instanceof Error ? err.message : String(err) }));
201	    }, Math.max(200, this.deps.tickMs ?? 1000));
202	    this.timer.unref?.();
203	  }
