// ─── pushes (s82) ──────────────────────────────────────────────────────

export type VetoPushPhase = "held" | "warning" | "running";

/** What every veto push carries (veto@1). URLs are absolute when the hub knows its public address. */
export interface VetoPushPayload {
  type: "veto";
  phase: VetoPushPhase;
  id: string;
  jobId: string;
  title: string;
  /** The command line, redacted and at most 200 characters ("" when AXHUB_VETO_PUSH_COMMAND=off or the tool has none). */
  command: string;
  runsAt: string;
  secondsLeft: number;
  denyUrl: string;
  streamUrl: string;
  approvalUrl: string;
}

const redactCommand = redactor();

/** The push for one phase. Pure, so tests pin exactly what leaves the hub. */
export function vetoPushPayload(c: Confirmation, phase: VetoPushPhase, now: string, opts: { publicUrl?: string; includeCommand?: boolean } = {}): VetoPushPayload {
  const base = opts.publicUrl && pushUrlAllowed(opts.publicUrl) ? opts.publicUrl.replace(/\/+$/, "") : "";
  const jobId = c.held?.jobId ?? "";
  const explain = approvalExplain(c, now);
  const raw = opts.includeCommand === false ? "" : (explain.code.command ?? "");
  const command = redactCommand(raw).replace(/[\u0000-\u0009\u000b-\u001f\u007f-\u009f]/g, "");
  return {
    type: "veto",
    phase,
    id: c.id,
    jobId,
    title: explain.title.slice(0, 120),
    command: command.length > 200 ? `${command.slice(0, 199)}…` : command,
    runsAt: c.veto?.runsAt ?? "",
    secondsLeft: phase === "running" ? 0 : vetoSecondsLeft(c, now),
    denyUrl: `${base}/auth/api/approvals/${c.id}/deny`,
    streamUrl: `${base}/auth/api/jobs/${jobId}/stream`,
    approvalUrl: `${base}/auth/admin/approvals/${c.id}`,
  };
}

/** Where Vinnie's pushes go. */
export interface VetoPushSender {
  send(payload: VetoPushPayload): Promise<boolean>;
}

/**
 * ntfy (the owner's existing push topic, AXHUB_PUSH_NTFY_*): the message body is the JSON payload for the AmberX app;
 * title, tags and the tap action are readable in any ntfy client. Same transport rules as approval pushes: https,
 * no redirects, short timeout, bounded rate; a failed push is logged and dropped, the call's countdown is unaffected.
 */
export function ntfyVetoSender(config: ApprovalPushConfig, deps: { log: Pick<Logger, "info" | "warn">; fetchImpl?: typeof fetch; timeoutMs?: number; maxPerWindow?: number; windowMs?: number }): VetoPushSender {
  const sent: number[] = [];
  return {
    async send(p) {
      try {
        const t = Date.now();
        const windowMs = deps.windowMs ?? 10 * 60_000;
        while (sent.length && t - sent[0]! > windowMs) sent.shift();
        if (sent.length >= (deps.maxPerWindow ?? 60)) {
          deps.log.warn("vinnie: push skipped, too many in a short time");
          return false;
        }
        sent.push(t);
        const mins = Math.floor(p.secondsLeft / 60);
        const left = `${mins}:${String(p.secondsLeft % 60).padStart(2, "0")}`;
        const title =
          p.phase === "held" ? `axHub: runs in ${left} unless you deny it` : p.phase === "warning" ? `axHub: ${p.secondsLeft} s left to deny` : "axHub: running now";
        const headers: Record<string, string> = { "content-type": "application/json" };
        if (config.token) headers.authorization = `Bearer ${config.token}`;
        const body: Record<string, unknown> = {
          topic: config.topic,
          title,
          message: JSON.stringify(p),
          priority: p.phase === "running" ? 4 : 5,
          tags: ["veto", p.phase],
        };
        if (/^https:\/\//.test(p.approvalUrl)) {
          body.click = p.approvalUrl;
          if (p.phase !== "running") body.actions = [{ action: "view", label: "Deny", url: p.approvalUrl, clear: true }];
        }
        const res = await (deps.fetchImpl ?? fetch)(config.url, { method: "POST", headers, body: JSON.stringify(body), redirect: "manual", signal: AbortSignal.timeout(deps.timeoutMs ?? 8000) });
        if (res.status >= 200 && res.status < 300) return true;
        deps.log.warn("vinnie: push refused by the push server", { status: res.status });
        return false;
      } catch (err) {
        deps.log.warn("vinnie: push failed", { errorName: err instanceof Error ? err.name : typeof err });
        return false;
      }
    },
  };
}

export interface VinnieDeps {
  hub: Pick<Hub, "settleVetoes" | "listHeldVetoes" | "events">;
  storage: Pick<Storage, "confirmations" | "jobs">;
  log: Pick<Logger, "info" | "warn">;
  now?: () => Date;
  /** Tick length (default 1000 ms). */
  tickMs?: number;
  /** Pushes (s82); off when unset. */
  push?: VetoPushSender;
  /** The hub's public address, for absolute links in pushes. */
  publicUrl?: string;
  /** Put the (redacted) command line in pushes (default true; AXHUB_VETO_PUSH_COMMAND=off). */
  pushCommand?: boolean;
}

export class Vinnie {
  private readonly jobs = new Map<string, JobRecord>();
  private timer: NodeJS.Timeout | undefined;
  private busy = false;
  private readonly running = new Set<Promise<void>>();
  /** Which phases were pushed per confirmation (in memory: after a restart a warning may repeat, never the reverse). */
  private readonly pushed = new Map<string, Set<VetoPushPhase>>();
  private unsubscribe: (() => void) | undefined;
  private readonly pushes = new Set<Promise<boolean>>();

  constructor(private readonly deps: VinnieDeps) {}

  /** Sends one phase once per call. Never throws; never blocks the countdown. */
  protected notify(c: Confirmation, phase: VetoPushPhase): void {
    const push = this.deps.push;
    if (!push || !c.veto || !c.held) return;
    let phases = this.pushed.get(c.id);
    if (!phases) this.pushed.set(c.id, (phases = new Set()));
    if (phases.has(phase)) return;
    phases.add(phase);
    const payload = vetoPushPayload(c, phase, this.nowIso(), { ...(this.deps.publicUrl ? { publicUrl: this.deps.publicUrl } : {}), includeCommand: this.deps.pushCommand !== false });
    const p = push.send(payload).catch(() => false);
    this.pushes.add(p);
    void p.finally(() => this.pushes.delete(p));
  }

  private nowIso(): string {
    return (this.deps.now ? this.deps.now() : new Date()).toISOString();
  }

  start(): void {
    if (this.timer) return;
    this.listen();
    this.timer = setInterval(() => {
      if (this.busy) return;
      void this.tick().catch((err) => this.deps.log.warn("vinnie: tick failed", { error: err instanceof Error ? err.message : String(err) }));
    }, Math.max(200, this.deps.tickMs ?? 1000));
    this.timer.unref?.();
  }

  /** Pushes `held` as soon as the hub holds a veto call (not only at the next tick). */
  listen(): void {
    if (this.unsubscribe || !this.deps.push) return;
    this.unsubscribe = this.deps.hub.events.subscribe((event) => {
      if (event.type !== "confirmation" || event.status !== "held") return;
      void this.deps.storage.confirmations
        .get(event.confirmationId)
        .then((c) => (c?.veto && c.status === "held" ? this.notify(c, "held") : undefined))
        .catch(() => undefined);
    });
  }

  stop(): void {
    this.unsubscribe?.();
    this.unsubscribe = undefined;
    if (this.timer) clearInterval(this.timer);
    this.timer = undefined;
    for (const r of this.jobs.values()) r.listeners.clear();
  }

  /** Waits for every run Vinnie started (tests, shutdown). */
  async idle(): Promise<void> {
    while (this.running.size || this.pushes.size) await Promise.allSettled([...this.running, ...this.pushes]);
  }

  /** One pass: countdowns (and warnings), then settle what is due. */
  async tick(): Promise<void> {
    if (this.busy) return;
    this.busy = true;
    try {
      const now = this.nowIso();
      for (const c of await this.deps.hub.listHeldVetoes()) this.countdown(c, now);
      const { runs } = await this.deps.hub.settleVetoes({
        onState: (change) => this.onState(change),
        onOutput: (chunk) => this.onOutput(chunk),
      });
      for (const run of runs) {
        this.running.add(run);
        void run.finally(() => this.running.delete(run));
      }
      this.sweep();
    } finally {
      this.busy = false;
    }
  }

  /** Called by the deny route so watchers hear "denied" now; the next tick closes the job. */
  denied(c: Confirmation): void {
    const jobId = c.held?.jobId;
    if (!jobId) return;
    this.setState(this.record(jobId, c.id, "held"), "denied", null);
  }

  // ─── what the hub tells Vinnie ────────────────────────────────────────

  protected countdown(c: Confirmation, now: string): void {
    const jobId = c.held!.jobId;
    const r = this.record(jobId, c.id, "held");
    const secondsLeft = vetoSecondsLeft(c, now);
    this.emit(r, { event: "countdown", data: { secondsLeft } });
    // A held push missed (hub restarted between hold and push) goes out with the first countdown.
    this.notify(c, "held");
    const warn = c.veto!.warningSeconds;
    if (warn > 0 && secondsLeft > 0 && secondsLeft <= warn) this.notify(c, "warning");
  }

  protected onState(change: VetoStateChange): void {
    const r = this.record(change.jobId, change.confirmationId, change.state);
    this.setState(r, change.state, change.exitCode ?? null);
    if (change.state === "running") this.notify(change.confirmation, "running");
    if (FINAL.includes(change.state)) setTimeout(() => this.pushed.delete(change.confirmationId), VINNIE_KEEP_MS).unref?.();
    if (change.state === "running") this.deps.log.info("vinnie: countdown ended, running", { confirmationId: change.confirmationId, jobId: change.jobId });
    if (change.state === "expired") this.deps.log.warn("vinnie: veto call expired without running", { confirmationId: change.confirmationId });
  }

  private onOutput(chunk: OutputChunk & { jobId: string }): void {
    const r = this.jobs.get(chunk.jobId);
    if (!r) return;
    const part: OutputChunk = { stream: chunk.stream, text: chunk.text };
    const size = Buffer.byteLength(part.text, "utf8");
    if (r.bytes + size <= VINNIE_REPLAY_BYTES) {
      r.output.push(part);
      r.bytes += size;
    }
    this.emit(r, { event: "output", data: part });

