async function confirmations(rt: Runtime, args: string[], flags: { yes?: boolean }): Promise<void> {
  const sub = args[0] ?? "list";
  const now = new Date().toISOString();
  switch (sub) {
    case "list": {
      const held = (await rt.storage.confirmations.list({ now, statuses: ["held"], limit: 100 })).filter((c) => c.veto && c.expiresAt > now);
      for (const c of held) {
        const left = Math.max(0, Math.ceil((Date.parse(c.veto!.runsAt) - Date.now()) / 1000));
        out(`${c.id}  VETO: runs in ${left} s unless denied (axhub confirmations deny ${c.id})${c.reason ? `  ${displaySafe(c.reason.title)}` : ""}`);
        out(`  ${displaySafe(c.summary)}`);
      }
      const pending = await rt.storage.confirmations.listPending(now);
      if (pending.length === 0) return out(held.length ? "Nothing else is waiting for approval." : "Nothing is waiting for approval.");
      for (const c of pending) {
        out(`${c.id}${c.reason ? `  ${displaySafe(c.reason.title)}` : ""}`);
        out(`  ${displaySafe(c.summary)}`);
        out(`  requested ${short(c.createdAt)}, expires ${short(c.expiresAt)}`);
      }
      return;
    }
    case "show": {
      const c = await rt.storage.confirmations.get(need(args, 1, "confirmation id"));
      if (!c) throw new AxHubError("not_found", "No confirmation with that id.");
      return printConfirmation(c);
    }
    case "deny": {
      // A veto call (decision #102): stops it before its countdown ends. The safe direction, so no y/N.
      const id = need(args, 1, "confirmation id");
      const c = await rt.storage.confirmations.get(id);
      if (!c) throw new AxHubError("not_found", "No confirmation with that id.");
      if (!c.veto) throw new AxHubError("conflict", "That request isn't on a veto countdown; use `confirmations reject`.");
      let next: Confirmation;
      try {
        next = applyApprovalAction(c, "deny", { now: new Date().toISOString(), by: "cli", ttlMs: 0 });
      } catch {
        throw new AxHubError("conflict", `Too late to deny it: it is ${c.status === "held" ? "past its time" : c.veto.state}.`);
      }
      if (!(await rt.storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 }))) {
        throw new AxHubError("conflict", "Too late to deny it: the countdown ended a moment ago and it is running.");
      }
      await audit(rt.storage, "confirmation_decided", "ok", `denied veto ${id}`);
      out("Denied. Vinnie won't run it.");
      return;
    }
    case "approve":
    case "reject": {
      const id = need(args, 1, "confirmation id");
      const existing = await rt.storage.confirmations.get(id);
      if (!existing) throw new AxHubError("not_found", "No confirmation with that id.");
      const decision = sub === "approve" ? "approved" : "rejected";
      if (decision === "approved") {
        // Approving is the dangerous direction: show exactly what will run, then ask.
        printConfirmation(existing);
        if (existing.veto) throw new AxHubError("conflict", "That is a veto call: it runs by itself when its countdown ends. To stop it, `axhub confirmations deny " + id + "`.");
        if (existing.status !== "pending" || existing.expiresAt <= now) {
          throw new AxHubError("conflict", `Can't approve it: ${existing.status !== "pending" ? `it is already ${existing.status}` : "it has expired"}.`);
        }
    // Not running in this process (left over from a restart): just record it.
    job.state = "cancelled";
    job.updatedAt = this.nowIso();
    job.result = {
      ...errorResult({ id: job.callId, correlationId: job.correlationId }, new AxHubError("cancelled", "Cancelled by the caller.")),
      jobId: job.id,
    };
    await this.storage.jobs.save(job);
    await this.audit("job_cancelled", "ok", undefined, { target: job.target, note: `job ${job.id}`, callerId: caller.id, via: caller.via });
    // The caller stopping its own veto call before it runs is a Deny (the safe direction; it can never hurry or un-deny one).
    if (job.confirmationId) {
      const c = await this.storage.confirmations.get(job.confirmationId);
      if (c?.veto && c.status === "held" && c.callerId === caller.id) {
        try {
          const next = applyApprovalAction(c, "deny", { now: this.nowIso(), by: `caller:${truncate(caller.id, 100)}`, ttlMs: 0 });
          await this.storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 });
        } catch {
          // already moved on
        }
      }
    }
    return job;
  }

