export const ConfirmationStatusSchema = z.enum(["pending", "approved", "rejected", "expired", "consumed", "postponed", "ignored", "revoked", "held"]);
export const VetoStateSchema = z.enum(["held", "shelved", "running", "ran", "failed", "denied", "expired"]);
export const VetoInfoSchema = z.object({
  seconds: z.number().int().positive(),
  warningSeconds: z.number().int().min(0),
  runsAt: TimestampSchema,
  state: VetoStateSchema,
  startedAt: TimestampSchema.optional(),
  finishedAt: TimestampSchema.optional(),
  exitCode: z.number().int().nullable().optional(),
  note: z.string().max(300).optional(),
});

export const PostponeConditionSchema = z.object({
  kind: z.string().regex(/^[a-z][a-z0-9-]{0,39}$/),
  params: z.record(z.string().max(40), z.string().max(500)).refine((p) => Object.keys(p).length <= 8, "Too many condition parameters."),
});

export const PostponementSchema = z.object({
  condition: PostponeConditionSchema,
  since: TimestampSchema,
  firstSince: TimestampSchema,
  return value === "allow" || value === "confirm" || value === "deny" || value === "veto";
}

/** Countdown defaults for `veto` tools (decision #102). */
export const VETO_DEFAULT_SECONDS = 180;
export const VETO_DEFAULT_WARNING_SECONDS = 30;
export const VETO_MIN_SECONDS = 10;
export const VETO_MAX_SECONDS = 1800;
/** A veto call is never run more than this late (the hub was down past its time): it expires instead. */
export const VETO_MAX_LATE_MS = 60_000;

/** The countdown for a veto tool, read as an own property only, always in range. */
export function vetoSettingsFor(service: Service, toolName: string): Required<VetoSettings> {
  const all = service.vetoSettings;
  const raw: VetoSettings = all && Object.hasOwn(all, toolName) && all[toolName] && typeof all[toolName] === "object" ? all[toolName]! : {};
  const int = (v: unknown, d: number) => (typeof v === "number" && Number.isInteger(v) ? v : d);
  const seconds = Math.min(VETO_MAX_SECONDS, Math.max(VETO_MIN_SECONDS, int(raw.vetoSeconds, VETO_DEFAULT_SECONDS)));
  let warning = Math.max(0, int(raw.vetoWarningSeconds, VETO_DEFAULT_WARNING_SECONDS));
  if (warning >= seconds) warning = Math.floor(seconds / 2);
  return { vetoSeconds: seconds, vetoWarningSeconds: warning };
}

export function strictest(a: PolicyDecision, b: PolicyDecision): PolicyDecision {
