/**
 * Approvals for the AXHub web app (decisions #82, #85, #87, #90, #94, #95; pages moved to the web app #96).
 *
 *   GET  /auth/api/approvals                 the grid: pending first, then postponed, newest first; filters, pages of 20
 *   GET  /auth/api/approvals/<id>            one request
 *   GET  /auth/api/approvals/<id>/postpone   presets, units and conditions for Postpone
 *   POST /auth/api/approvals/<id>            {action: approve | decline | postpone | ignore | revoke | reopen | deny, rev, postpone?}
 *   POST /auth/api/approvals/<id>/deny       {rev?} stops a veto call before its countdown ends (decision #102, veto@1)
 *   POST /auth/api/approvals/auto            {minutes} opens the auto-approve window; /auto/stop ends it
 *   GET  /auth/api/approvals/log             the approvals log (filtered + paged); /auth/admin/approvals/log.json downloads it
 *   GET  /auth/admin/approvals.json          the feed for banners (pending as before + postponed, reminders, review)
 *   GET  /auth/admin/approvals[/<id>[/postpone]|/log]  the old pages: send the browser to the same place in the web app
 *
 * Rules that hold for every action: a signed-in admin's browser session only (the MCP bearer token never reaches these
 * routes, so an AI client can never decide its own call), the hub's own Origin, the session's CSRF token in a header,
 * a JSON body, the request's revision when the app sends one (a row that changed since it was drawn is refused, so a tap
 * never lands on a different state than the one shown), compare-and-set in storage, and an audit entry. The web app
 * shows Approve on a collapsed row only when that row shows the complete call (`whole`); otherwise under the full call.
 * Nothing changes what an approval is bound to (caller, tool, exact arguments).
 */
import { randomUUID } from "node:crypto";
import express, { type NextFunction, type Request, type Response, type Router } from "express";
import {
  APPROVAL_STATUS_LABELS,
  AxHubError,
  MAX_POSTPONE_MS,
  SCHEMA_VERSION,
  allowedActions,
  applyApprovalAction,
  displaySafe,
  effectiveStatus,
  postponeDeadline,
  remindAt,
  reviewRequired,
  type ApprovalAction,
  type Confirmation,
  type ConfirmationStatus,
  type PostponeCondition,
  type Storage,
  type VetoState,
} from "@axhub/core";
import type { SignedIn } from "./accounts.js";
import type { ConditionContext, ConditionRegistry } from "./approval-conditions.js";
import type { Logger } from "./logger.js";
import { AUTO_APPROVE_MINUTES, type ApprovalLog, type ApprovalLogEntry } from "./approval-log.js";

export interface ApprovalsWebDeps {
  storage: Pick<Storage, "confirmations" | "audit">;
  conditions: ConditionRegistry;
  conditionContext?: Omit<ConditionContext, "now">;
  /** Use window when a request returns to pending or is approved from a postponement (the hub's TTL, 30 min). */
  ttlMs: number;
  log: Logger;
  fmt: (iso: string) => string;
  /** Fixed message text by key (our own words, never user input). */
  messages: Record<string, string>;
  /** API guard: signed in (admin when asked); writes also need the hub's Origin, the CSRF header and a JSON body. */
  api: (adminOnly?: boolean) => (req: Request, res: Response, next: NextFunction) => Promise<unknown>;
  /** Cookie-session page guard (only the log download uses it). */
  signedIn: (adminOnly?: boolean) => (req: Request, res: Response, next: NextFunction) => Promise<unknown>;
  current: (req: Request) => Promise<SignedIn | undefined>;
  hubOrigin: (req: Request) => string;
  feedOriginOk: (origin: string) => boolean;
  /** Sends a browser to a route of the AXHub web app (the hub's pages), e.g. `approvals/<id>`. */
  toWebApp: (req: Request, res: Response, route: string) => void;
  /** Auto-approve window + approvals log (decision #94). */
  approvalLog?: ApprovalLog;
  /** Told when a veto call is denied here (decision #102), so Vinnie stops the countdown at once. */
  onVetoDenied?: (c: Confirmation) => void;
  now?: () => Date;
}

export const APPROVALS_PAGE_SIZE = 20;
/** A call this short is shown whole on its collapsed row, so the row may carry Approve. */
export const ONE_LINE_MAX = 160;

/** Grid filters → stored statuses. */
export const APPROVAL_FILTERS: Record<string, { label: string; statuses?: ConfirmationStatus[] }> = {
  all: { label: "All" },
