/**
 * Vinnie (decision #102, veto@1): axHub's own agent for veto calls.
 *
 * A tool with policy `veto` (e.g. `vps.run`) is not refused while it waits: the hub holds the call with a countdown
 * (default 180 s) and answers at once with `held: true`. Vinnie
 *   - ticks every second: sends `countdown` to everyone watching a held call's job stream;
 *   - runs the call when its countdown ends (through the hub's normal single-use approval check, as the caller that
 *     asked), unless the owner denied it first; never more than 60 s late (the hub was down): it expires instead;
 *   - streams the command's output (already redacted by the connector, inside its 256 KB cap) to the job stream;
 *   - closes the jobs of denied or expired calls;
 *   - pushes three notifications through the owner's ntfy topic (the channel the AmberX Android app delivers):
 *     `held` when the countdown starts, `warning` at `vetoWarningSeconds` left (default 30), `running` when it starts.
 *     The payload is JSON (`vetoPushPayload`); the feed (`/auth/admin/approvals.json`) stays the primary path and the
 *     push is the wake-up.
 *
 *   GET /auth/api/jobs/<jobId>/stream   SSE: countdown {secondsLeft} · state {state} · output {stream, text} · done {state, exitCode}
 *
 * Who may watch: a signed-in admin's browser session (any veto job), or the bearer token of the caller that made the
 * call (its own jobs only). Read-only: nothing here approves or un-denies anything. Deny lives in approvals-web.ts.
 */
import express, { type Request, type Response } from "express";
import type { Confirmation, Hub, OutputChunk, Storage, VetoState, VetoStateChange } from "@axhub/core";
import { redactor } from "@axhub/connector-ssh";
import { approvalExplain, vetoSecondsLeft, vetoStateOf } from "./approvals-web.js";
import { pushUrlAllowed, type ApprovalPushConfig } from "./approval-push.js";
import type { Logger } from "./logger.js";

export type VinnieEvent =
  | { event: "countdown"; data: { secondsLeft: number } }
  | { event: "state"; data: { state: VetoState } }
  | { event: "output"; data: OutputChunk }
  | { event: "done"; data: { state: VetoState; exitCode: number | null } };

type Listener = (ev: VinnieEvent) => void;

/** Output kept per job for late watchers: both streams' caps (256 KB each) and a little room. */
export const VINNIE_REPLAY_BYTES = 2 * 256 * 1024;
/** How long a finished job's output stays replayable in memory. */
export const VINNIE_KEEP_MS = 15 * 60 * 1000;
export const VINNIE_HEARTBEAT_MS = 25_000;
const FINAL: readonly VetoState[] = ["ran", "failed", "denied", "expired"];

interface JobRecord {
  jobId: string;
  confirmationId: string;
  state: VetoState;
  output: OutputChunk[];
  bytes: number;
  exitCode: number | null;
  finishedAt?: number;

content.content:
290	  }
291	
292	  private setState(r: JobRecord, state: VetoState, exitCode: number | null): void {
293	    const changed = r.state !== state;
294	    r.state = state;
295	    if (exitCode !== null) r.exitCode = exitCode;
296	    if (changed || FINAL.includes(state)) this.emit(r, { event: "state", data: { state } });
297	    if (FINAL.includes(state) && r.finishedAt === undefined) {
298	      r.finishedAt = Date.now();
299	      this.emit(r, { event: "done", data: { state, exitCode: r.exitCode } });
300	    }
301	  }
302	
303	  private record(jobId: string, confirmationId: string, state: VetoState): JobRecord {
304	    let r = this.jobs.get(jobId);
305	    if (!r) {
306	      r = { jobId, confirmationId, state, output: [], bytes: 0, exitCode: null, listeners: new Set() };
307	      this.jobs.set(jobId, r);
308	    }
309	    return r;
310	  }
311	
312	  private emit(r: JobRecord, ev: VinnieEvent): void {
313	    for (const l of [...r.listeners]) {
314	      try {
315	        l(ev);
316	      } catch {
317	        r.listeners.delete(l);
318	      }
319	    }
320	  }
321	
322	  private sweep(): void {
323	    const cutoff = Date.now() - VINNIE_KEEP_MS;
324	    for (const [id, r] of this.jobs) if (r.finishedAt !== undefined && r.finishedAt < cutoff && r.listeners.size === 0) this.jobs.delete(id);
325	  }
326	
327	  // ─── the job stream ───────────────────────────────────────────────────
328	
329	  /**
330	   * Opens a watch on one veto job: first what is known now (state, countdown or replayed output, done), then live
331	   * events. Returns undefined for a job that isn't a veto call. The listener is called synchronously.
332	   */
333	  async watch(jobId: string, listener: Listener): Promise<{ close(): void; finished: boolean } | undefined> {
334	    const job = await this.deps.storage.jobs.get(jobId);
335	    if (!job?.confirmationId) return undefined;
336	    const c = await this.deps.storage.confirmations.get(job.confirmationId);
337	    if (!c?.veto || c.held?.jobId !== jobId) return undefined;
338	    const now = this.nowIso();
339	    const r = this.record(jobId, c.id, vetoStateOf(c, now));
340	    // Storage is the truth for anything Vinnie didn't see in this process (restart, the CLI's deny).
341	    const stored = vetoStateOf(c, now);
342	    if (r.finishedAt === undefined && FINAL.includes(stored)) {
343	      r.state = stored;
344	      r.exitCode = c.veto.exitCode ?? null;
