  }

  private setState(r: JobRecord, state: VetoState, exitCode: number | null): void {
    const changed = r.state !== state;
    r.state = state;
    if (exitCode !== null) r.exitCode = exitCode;
    if (changed || FINAL.includes(state)) this.emit(r, { event: "state", data: { state } });
    if (FINAL.includes(state) && r.finishedAt === undefined) {
      r.finishedAt = Date.now();
      this.emit(r, { event: "done", data: { state, exitCode: r.exitCode } });
    }
  }

  private record(jobId: string, confirmationId: string, state: VetoState): JobRecord {
    let r = this.jobs.get(jobId);
    if (!r) {
      r = { jobId, confirmationId, state, output: [], bytes: 0, exitCode: null, listeners: new Set() };
      this.jobs.set(jobId, r);
    }
    return r;
  }

  private emit(r: JobRecord, ev: VinnieEvent): void {
    for (const l of [...r.listeners]) {
      try {
        l(ev);
      } catch {
        r.listeners.delete(l);
      }
    }
  }

  private sweep(): void {
    const cutoff = Date.now() - VINNIE_KEEP_MS;
    for (const [id, r] of this.jobs) if (r.finishedAt !== undefined && r.finishedAt < cutoff && r.listeners.size === 0) this.jobs.delete(id);
  }

  // ─── the job stream ───────────────────────────────────────────────────

  /**
   * Opens a watch on one veto job: first what is known now (state, countdown or replayed output, done), then live
   * events. Returns undefined for a job that isn't a veto call. The listener is called synchronously.
   */
  async watch(jobId: string, listener: Listener): Promise<{ close(): void; finished: boolean } | undefined> {
    const job = await this.deps.storage.jobs.get(jobId);
    if (!job?.confirmationId) return undefined;
    const c = await this.deps.storage.confirmations.get(job.confirmationId);
    if (!c?.veto || c.held?.jobId !== jobId) return undefined;
    const now = this.nowIso();
    const r = this.record(jobId, c.id, vetoStateOf(c, now));
    // Storage is the truth for anything Vinnie didn't see in this process (restart, the CLI's deny).
    const stored = vetoStateOf(c, now);
    if (r.finishedAt === undefined && FINAL.includes(stored)) {
      r.state = stored;
      r.exitCode = c.veto.exitCode ?? null;
      r.finishedAt = Date.now();
    }
    listener({ event: "state", data: { state: r.state } });
    if (r.state === "held") listener({ event: "countdown", data: { secondsLeft: vetoSecondsLeft(c, now) } });
    for (const part of r.output) listener({ event: "output", data: part });
    if (r.finishedAt !== undefined) {
      listener({ event: "done", data: { state: r.state, exitCode: r.exitCode } });
      return { close: () => undefined, finished: true };
    }
    r.listeners.add(listener);
    return { close: () => r.listeners.delete(listener), finished: false };
  }
}

/** Who is asking for a job stream: an admin browser session, or the caller behind a bearer token. */
export type StreamViewer = { kind: "admin"; id: string } | { kind: "caller"; id: string };

export interface VinnieRouteDeps {
  vinnie: Vinnie;
  storage: Pick<Storage, "jobs" | "confirmations">;
  /** Resolves the viewer (bearer token first, else the admin session cookie); undefined = not allowed. */
  viewer: (req: Request) => Promise<StreamViewer | undefined>;
  hubOrigin: (req: Request) => string;
  /** Cross-site browsers allowed to read the stream with the hub session (same rule as the approvals feed). */
  originOk: (origin: string) => boolean;
  heartbeatMs?: number;
}

const JOB_RE = /^[0-9a-f-]{36}$/;

export function vinnieRouter(d: VinnieRouteDeps): express.Router {
  const r = express.Router();
  r.get("/auth/api/jobs/:jobId/stream", async (req: Request, res: Response) => {
    res.set("Cache-Control", "no-store");
    res.set("Vary", "Origin, Cookie, Authorization");
    const origin = req.header("origin");
    if (origin && origin.replace(/\/+$/, "").toLowerCase() !== d.hubOrigin(req).toLowerCase()) {
      if (!d.originOk(origin)) return res.status(403).json({ error: { code: "denied", message: "Not allowed from this site." } });
      res.set("Access-Control-Allow-Origin", origin);
      res.set("Access-Control-Allow-Credentials", "true");
    }
    const viewer = await d.viewer(req).catch(() => undefined);
    if (!viewer) return res.status(401).json({ error: { code: "unauthenticated", message: "Sign in on the hub as an admin, or send the caller's bearer token." } });
    const jobId = String(req.params.jobId);
    const job = JOB_RE.test(jobId) ? await d.storage.jobs.get(jobId) : undefined;
    // Callers see their own jobs only; anything else looks like it doesn't exist.
    const c = job?.confirmationId ? await d.storage.confirmations.get(job.confirmationId) : undefined;
    if (!job || !c?.veto || c.held?.jobId !== job.id || (viewer.kind === "caller" && job.callerId !== viewer.id)) {
      return res.status(404).json({ error: { code: "not_found", message: "No veto job with that id." } });
    }

    res.status(200);
    res.set("Content-Type", "text/event-stream; charset=utf-8");
    res.set("Connection", "keep-alive");
    res.set("X-Accel-Buffering", "no");
    let open = true;
    const send = (ev: VinnieEvent) => {
      if (!open) return;
      res.write(`event: ${ev.event}\ndata: ${JSON.stringify(ev.data)}\n\n`);
      if (ev.event === "done") end();
    };
    let heartbeat: NodeJS.Timeout | undefined;
    let watch: { close(): void } | undefined;
    const end = () => {
      if (!open) return;
      open = false;
      if (heartbeat) clearInterval(heartbeat);
      watch?.close();
      res.end();
    };
    res.flushHeaders?.();
    res.write(": vinnie\n\n");
    const w = await d.vinnie.watch(jobId, send);
    if (!w) {
      res.write(`event: error\ndata: ${JSON.stringify({ code: "not_found", message: "That job isn't a veto call." })}\n\n`);
      return end();
    }
    watch = w;
    if (!open) return;
    heartbeat = setInterval(() => open && res.write(": ping\n\n"), d.heartbeatMs ?? VINNIE_HEARTBEAT_MS);
    heartbeat.unref?.();
    req.on("close", end);
  });
  return r;
}

