async function setup(reg: Record<string, unknown> = {}) {
  const clock = { now: T0 };
  const storage = new MemoryStorage();
  const vault = new EnvelopeVault(storage.secrets, KeyRing.fromEncoded(generateMasterKey()));
  const f = fake();
  const hub = new Hub({ storage, vault, connectors: [f.connector], version: "test", syncWaitMs: 1000, now: () => new Date(clock.now) });
  await new Registry(storage).register(
    { namespace: "vps", type: "rest", displayName: "VPS", toolPolicies: { run: "veto", check: "allow" }, vetoSettings: { run: { vetoSeconds: 180, vetoWarningSeconds: 30 } }, ...reg },
    ACTOR,
  );
  await hub.start();
  return { hub, storage, vault, f, clock };
}

async function hold(hub: Hub, extra: Partial<Call> = {}) {
  const r = await hub.call(mkCall("run", { command: "echo hi" }, extra));
  expect(r.status).toBe("error");
  expect(r.error?.code).toBe("confirmation_required");
  const d = r.error!.details!;
  expect(d.veto).toBe(true);
  expect(d.held).toBe(true);
  return { id: String(d.confirmationId), jobId: String(d.jobId), runsAt: String(d.runsAt), details: d };
}

function recorder() {
  const states: VetoStateChange[] = [];
  const output: (OutputChunk & { jobId: string })[] = [];
  return { states, output, hooks: { onState: (s: VetoStateChange) => states.push(s), onOutput: (o: OutputChunk & { jobId: string }) => output.push(o) } };
}

describe("veto policy (decision #102)", () => {
  const svc = (p: Partial<Service>): Service => ({
    schemaVersion: SCHEMA_VERSION, namespace: "vps", type: "ssh", displayName: "v", enabled: true, status: "online",
    capabilities: { streaming: false, progress: false, cancellation: false, files: false, jobs: false }, defaultPolicy: "deny",
    createdAt: new Date(T0).toISOString(), updatedAt: new Date(T0).toISOString(), ...p,
  });
