describe("Approve now and Shelve (decision #104)", () => {
  const act = async (storage: MemoryStorage, id: string, action: "approve-now" | "shelve" | "deny", at: number) => {
    const c = (await storage.confirmations.get(id))!;
    const next = applyApprovalAction(c, action, { now: new Date(at).toISOString(), by: "web:admin", ttlMs: 0 });
    expect(await storage.confirmations.replace(next, { status: c.status, revision: c.revision ?? 0 })).toBe(true);
    return next;
  };

  it("Approve now runs it at the next pass, before the countdown would have ended", async () => {
    const { hub, storage, f, clock } = await setup();
    const { id, jobId } = await hold(hub);
    clock.now = T0 + 20_000;
    const next = await act(storage, id, "approve-now", clock.now);
    expect(next.status).toBe("held");
    expect(next.veto).toMatchObject({ runsAt: new Date(T0 + 20_000).toISOString(), approvedNowBy: "web:admin" });
    expect(allowedActions(next, new Date(clock.now).toISOString())).toEqual(["deny"]);
    clock.now += 300;
    const r = await hub.settleVetoes();
    expect(r.settled).toBe(1);
    await Promise.all(r.runs);
    expect(f.state.runs).toHaveLength(1);
    expect((await hub.getJob(OWNER, jobId)).state).toBe("succeeded");
    expect((await storage.confirmations.get(id))?.veto?.state).toBe("ran");
  });

  it("Shelve pauses the countdown: nothing runs past runsAt until Approve now", async () => {
    const { hub, storage, f, clock } = await setup();
    const { id, jobId } = await hold(hub);
    clock.now = T0 + 100_000;
    const shelved = await act(storage, id, "shelve", clock.now);
    expect(shelved.veto).toMatchObject({ state: "shelved", shelvedSecondsLeft: 80 });
    expect(allowedActions(shelved, new Date(clock.now).toISOString())).toEqual(["approve-now", "deny"]);
    // an hour past its old time: still waiting, nothing ran, not expired
    clock.now = T0 + 3_600_000;
    expect((await hub.settleVetoes()).settled).toBe(0);
    expect(f.state.runs).toHaveLength(0);
    expect((await hub.getJob(OWNER, jobId)).state).toBe("awaiting_confirmation");
    expect(() => applyApprovalAction(shelved, "shelve", { now: new Date(clock.now).toISOString(), by: "web:admin", ttlMs: 0 })).toThrow(AxHubError);
    await act(storage, id, "approve-now", clock.now);
    const r = await hub.settleVetoes();
    await Promise.all(r.runs);
    expect(f.state.runs).toHaveLength(1);
  });

  it("a shelved call can be denied, and one never decided expires after 7 days without running", async () => {
    const { hub, storage, f, clock } = await setup();
    const a = await hold(hub);
    await act(storage, a.id, "shelve", T0 + 1000);
    await act(storage, a.id, "deny", T0 + 2000);
    clock.now = T0 + 3000;
    await hub.settleVetoes();
    expect((await hub.getJob(OWNER, a.jobId)).state).toBe("cancelled");
    const b = await hold(hub);
    await act(storage, b.id, "shelve", clock.now + 1000);
    clock.now = T0 + 8 * 24 * 3_600_000;
    const rec = recorder();
    await hub.settleVetoes(rec.hooks);
    expect(rec.states.map((s) => s.state)).toEqual(["expired"]);
    expect((await hub.getJob(OWNER, b.jobId)).state).toBe("cancelled");
    expect(f.state.runs).toHaveLength(0);
  });

  it("the caller can never approve, hurry or shelve its own call: cancelling is only ever a Deny", async () => {
    const { hub, storage, f, clock } = await setup();
    const { id, jobId } = await hold(hub);
    const retry = await hub.call(mkCall("run", { command: "echo hi" }, { confirmationId: id }));
    expect(retry.error?.code).toBe("confirmation_required");
    await hub.cancelJob(OWNER, jobId);
    expect((await storage.confirmations.get(id))?.status).toBe("rejected");
    clock.now = T0 + 200_000;
    await hub.settleVetoes();
    expect(f.state.runs).toHaveLength(0);
  });
});
EOF
