/**
 * Veto calls through the server (decision #102, veto@1): the held answer, the feeds' fields, Deny (admin session +
 * Origin + CSRF, revision-checked, audited; never the bearer token), Vinnie's job stream, expiry, the CLI.
 */
import { spawnSync } from "node:child_process";
import { mkdtempSync, rmSync } from "node:fs";
import type { AddressInfo } from "node:net";
import type { Server } from "node:http";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import {
  EnvelopeVault, Hub, KeyRing, MemoryStorage, PLUGIN_API_VERSION, Registry, SCHEMA_VERSION, generateMasterKey, okResult,
  type Call, type Caller, type OutboundConnector, type Tool,
} from "@axhub/core";
import { SqliteStorage } from "@axhub/storage-sqlite";
import { Accounts } from "../src/accounts.js";
import { createApp, type AxHubApp } from "../src/app.js";
import { loadConfig } from "../src/config.js";
import { createLogger } from "../src/logger.js";
import { resultToMcp } from "../src/mcp.js";
import { Vinnie, ntfyVetoSender, vetoPushPayload, type VetoPushPayload } from "../src/vinnie.js";

const TOKEN = `test-${crypto.randomUUID()}-${crypto.randomUUID()}`;
const ADMIN_PW = `pw-${crypto.randomUUID()}`;
const OWNER: Caller = { schemaVersion: SCHEMA_VERSION, id: "owner", kind: "ai_client", scopes: ["*"], via: "mcp" };
let clock = Date.parse("2026-10-28T22:00:00.000Z");
const now = () => new Date(clock);
let storage: MemoryStorage;
let hub: Hub;
let vinnie: Vinnie;
let hubApp: AxHubApp;
let server: Server;
let base: string;
const runs: Call[] = [];
let gate: Promise<void> = Promise.resolve();

const tool = (name: string, annotations?: Tool["annotations"]): Tool => ({
  schemaVersion: SCHEMA_VERSION, service: "vps", name, qualifiedName: `vps.${name}`, description: `${name} on the VPS`, inputSchema: { type: "object" },
  ...(annotations ? { annotations } : {}),
});
const fake: OutboundConnector = {
  info: { id: "fake-ssh", version: "0", apiVersion: PLUGIN_API_VERSION },
  serviceTypes: ["rest"],
  capabilities: { streaming: false, progress: false, cancellation: true, files: false, jobs: false },
  async listTools() {
    return [tool("run", { destructive: true }), tool("check", { readOnly: true })];
  },
  async invoke(call, ctx) {
    runs.push(call);
    ctx.emitOutput?.({ stream: "stdout", text: "hello\n" });
    await gate;
    ctx.emitOutput?.({ stream: "stderr", text: "bye\n" });
    return okResult(call, [{ type: "text", text: "ran" }], { exitCode: 0 });
  },
};

beforeAll(async () => {
  const config = loadConfig({ AXHUB_MCP_TOKEN: TOKEN, AXHUB_SECURE_COOKIES: "off", AXHUB_COOKIE_DOMAIN: ".example.test", AXHUB_LOG_LEVEL: "error" });
  storage = new MemoryStorage();
  const vault = new EnvelopeVault(storage.secrets, KeyRing.fromEncoded(generateMasterKey()));
  const log = createLogger("error", () => undefined);
  hub = new Hub({ storage, vault, connectors: [fake], version: "test", logger: log, now });
  await hub.start();
  await new Registry(storage).register(
    { namespace: "vps", type: "rest", displayName: "VPS", toolPolicies: { run: "veto", check: "allow" }, vetoSettings: { run: { vetoSeconds: 180 } } },
    { callerId: "test", via: "test" },
  );
  const accounts = new Accounts(storage);
  await accounts.bootstrap("admin", ADMIN_PW);
  vinnie = new Vinnie({ hub, storage, log, now });
  hubApp = createApp(config, hub, log, accounts, storage, { approvals: { ttlMs: 30 * 60_000, now, onVetoDenied: (c) => vinnie.denied(c) }, vinnie });
  server = hubApp.app.listen(0, "127.0.0.1");
  await new Promise<void>((r) => server.once("listening", () => r()));
  base = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
});

afterAll(async () => {
  vinnie.stop();
  await hubApp.close();
  await new Promise<void>((r) => server.close(() => r()));
});

const get = (path: string, headers: Record<string, string> = {}) => fetch(`${base}${path}`, { redirect: "manual", headers });
async function signIn(): Promise<string> {
  const r = await fetch(`${base}/auth/login`, { method: "POST", redirect: "manual", headers: { "content-type": "application/x-www-form-urlencoded" }, body: new URLSearchParams({ username: "admin", password: ADMIN_PW, rd: "/" }).toString() });
  expect(r.status).toBe(303);
  return (r.headers.get("set-cookie") ?? "").split(";")[0]!;
}
const csrfOf = async (cookie: string) => ((await (await get("/auth/api/session", { cookie })).json()) as { csrf?: string }).csrf ?? "";
const deny = (id: string, cookie: string, csrf: string, body: Record<string, unknown> = {}, origin: string | null = base, extra: Record<string, string> = {}) =>
  fetch(`${base}/auth/api/approvals/${id}/deny`, {
    method: "POST",
    redirect: "manual",
    headers: { "content-type": "application/json", cookie, ...(csrf ? { "x-axhub-csrf": csrf } : {}), ...(origin ? { origin } : {}), ...extra },
    body: JSON.stringify(body),
  });

let seq = 0;
async function holdOne(command = "echo hi") {
  seq += 1;
  const result = await hub.call({
    schemaVersion: SCHEMA_VERSION, id: `c-${seq}`, correlationId: `k-${seq}`, caller: OWNER, target: { service: "vps", tool: "run" },
    arguments: { command }, requestedAt: now().toISOString(), reason: { title: `Say ${command}`, description: "Test command." }, reasonRequired: true,
  });
  const d = result.error!.details!;
  return { result, id: String(d.confirmationId), jobId: String(d.jobId), runsAt: String(d.runsAt) };
}

/** Reads SSE events until `done` (or the limit). */
async function readStream(res: Response, onEvent?: (name: string, data: unknown) => Promise<void> | void, limit = 200) {
  const events: { event: string; data: unknown }[] = [];
  const reader = res.body!.getReader();
  const dec = new TextDecoder();
  let buf = "";
  while (events.length < limit) {
    const { value, done } = await reader.read();
    if (done) break;
    buf += dec.decode(value, { stream: true });
    let i: number;
    while ((i = buf.indexOf("\n\n")) >= 0) {
      const block = buf.slice(0, i);
      buf = buf.slice(i + 2);
      const ev = /^event: (.+)$/m.exec(block)?.[1];
      const data = /^data: (.+)$/m.exec(block)?.[1];
      if (!ev || data === undefined) continue;
      const parsed = JSON.parse(data) as unknown;
      events.push({ event: ev, data: parsed });
      await onEvent?.(ev, parsed);
      if (ev === "done") {
        await reader.cancel().catch(() => undefined);
        return events;
      }
    }
  }
  await reader.cancel().catch(() => undefined);
  return events;
}

describe("veto calls on the server (decision #102)", () => {
describe("veto calls on the server (decision #102)", () => {
  it("answers a veto call at once with held: true (an MCP result, not an error)", async () => {
    const { result, id, jobId, runsAt } = await holdOne();
    const mcp = resultToMcp(result, "https://axhub.example.test/auth/admin/approvals");
    expect(mcp.isError).toBeUndefined();
    const body = JSON.parse((mcp.content[0] as { text: string }).text) as Record<string, unknown>;
    expect(body).toMatchObject({
      held: true,
      id,
      jobId,
      runsAt,
      secondsLeft: 180,
      approvalUrl: `https://axhub.example.test/auth/admin/approvals/${id}`,
      denyUrl: `/auth/api/approvals/${id}/deny`,
      streamUrl: `/auth/api/jobs/${jobId}/stream`,
    });
    expect(String(body.next_step)).toContain("Don't call it again");
    expect(runs).toHaveLength(0);
  });

  it("puts held calls in the feeds with their countdown, links and Deny only", async () => {
    const { id, jobId, runsAt } = await holdOne("uptime");
    clock += 20_000;
    const cookie = await signIn();
    const feed = (await (await get("/auth/admin/approvals.json", { cookie })).json()) as Record<string, any>;
    const item = (feed.pending as any[]).find((p) => p.id === id);
    expect(item).toMatchObject({ status: "held", jobId, denyUrl: `/auth/api/approvals/${id}/deny`, streamUrl: `/auth/api/jobs/${jobId}/stream`, command: "uptime" });
    expect(item.veto).toMatchObject({ state: "held", runsAt, secondsLeft: 160, countdownSeconds: 180, warningSeconds: 30 });
    expect(feed.heldCount).toBeGreaterThanOrEqual(1);
    expect((feed.held as any[]).some((h) => h.id === id)).toBe(true);
    expect(feed.count).toBeGreaterThanOrEqual(feed.heldCount);

    const grid = (await (await get("/auth/api/approvals", { cookie })).json()) as Record<string, any>;
    expect(grid.heldCount).toBeGreaterThanOrEqual(1);
    const row = (grid.pending as any[]).find((p) => p.id === id);
    expect(row).toMatchObject({ status: "held", statusLabel: "Counting down", actions: ["deny"], jobId });
    expect(row.veto).toMatchObject({ runsAt, secondsLeft: 160, countdownSeconds: 180 });

    const one = (await (await get(`/auth/api/approvals/${id}`, { cookie })).json()) as { item: Record<string, any> };
    expect(one.item).toMatchObject({ status: "held", title: "Say uptime", veto: { state: "held", secondsLeft: 160, countdownSeconds: 180 } });
    expect(one.item.code.command).toBe("uptime");
  });

  it("Deny needs an admin session, the hub's Origin and CSRF; it is revision-checked, audited and final", async () => {
    const { id, jobId } = await holdOne("reboot");
    const cookie = await signIn();
    const clockFn = () => new Date(t);
    const s = new MemoryStorage();
    const vault = new EnvelopeVault(s.secrets, KeyRing.fromEncoded(generateMasterKey()));
    const h = new Hub({ storage: s, vault, connectors: [fake], version: "test", now: clockFn });
    await h.start();
    await new Registry(s).register(
      { namespace: "vps", type: "rest", displayName: "VPS", toolPolicies: { run: "veto" }, vetoSettings: { run: { vetoSeconds: 60, vetoWarningSeconds: 20 } } },
      { callerId: "test", via: "test" },
    );
    const sent: VetoPushPayload[] = [];
    const v = new Vinnie({ hub: h, storage: s, log: createLogger("error", () => undefined), now: clockFn, publicUrl: "https://axhub.example.test", push: { send: async (p) => (sent.push(p), true) } });
    v.listen();
    const hold = async (command: string) => {
      const r = await h.call({
        schemaVersion: SCHEMA_VERSION, id: crypto.randomUUID(), correlationId: "k", caller: OWNER, target: { service: "vps", tool: "run" },
        arguments: { command }, requestedAt: clockFn().toISOString(), reason: { title: "Restart the console", description: "Test." },
      });
      return { id: String(r.error!.details!.confirmationId), jobId: String(r.error!.details!.jobId) };
    };
    return { h, s, v, sent, hold, advance: (ms: number) => (t += ms) };
  }

  it("pushes held at once, warning at the configured seconds left (once), running when it starts", async () => {
    const { v, sent, hold, advance } = await rig();
    const { id, jobId } = await hold("docker restart axf-console");
    await new Promise((r) => setTimeout(r, 20));
    expect(sent.map((p) => p.phase)).toEqual(["held"]);
    expect(sent[0]).toEqual({
      type: "veto", phase: "held", id, jobId, title: "Restart the console", command: "docker restart axf-console",
      runsAt: "2026-10-28T23:01:00.000Z", secondsLeft: 60,
      denyUrl: `https://axhub.example.test/auth/api/approvals/${id}/deny`,
      streamUrl: `https://axhub.example.test/auth/api/jobs/${jobId}/stream`,
      approvalUrl: `https://axhub.example.test/auth/admin/approvals/${id}`,
    });
    advance(30_000);
    await v.tick();
    expect(sent.map((p) => p.phase)).toEqual(["held"]);
    advance(15_000);
    await v.tick();
    await v.tick();
    expect(sent.map((p) => p.phase)).toEqual(["held", "warning"]);
    expect(sent[1]!.secondsLeft).toBe(15);
    advance(16_000);
    await v.tick();
    await v.idle();
    expect(sent.map((p) => p.phase)).toEqual(["held", "warning", "running"]);
    expect(sent[2]!.secondsLeft).toBe(0);
    v.stop();
  });

  it("a denied call gets no warning or running push", async () => {
    const { s, v, sent, hold, advance } = await rig();
    const { id } = await hold("reboot");
    const c = (await s.confirmations.get(id))!;
    const { applyApprovalAction } = await import("@axhub/core");
    await s.confirmations.replace(applyApprovalAction(c, "deny", { now: c.createdAt, by: "web:admin", ttlMs: 0 }), { status: "held", revision: 0 });
    advance(50_000);
    await v.tick();
    advance(20_000);
    await v.tick();
    await v.idle();
    expect(sent.map((p) => p.phase)).toEqual(["held"]);
    v.stop();
  });

  it("redacts and shortens the command, and can leave it out", () => {
    const c = {
      schemaVersion: SCHEMA_VERSION, id: "6f1c2b9e-3d4a-4e7b-9a51-0c2d8e7f1a23", callId: "c", correlationId: "c", callerId: "owner",
      target: { service: "vps", tool: "run" }, fingerprint: "f", status: "held" as const, createdAt: "2026-10-28T23:00:00.000Z", expiresAt: "2026-10-28T23:04:00.000Z",
      summary: `vps.run with arguments ${JSON.stringify({ command: `curl -H "Authorization: Bearer abcdefghijklmnopqrstuv" ${"x".repeat(300)}` })}`,
      held: { arguments: {}, caller: OWNER, jobId: "b0e4d1c2-7a8f-4c3d-9e21-5f6a7b8c9d0e" },
      veto: { seconds: 180, warningSeconds: 30, runsAt: "2026-10-28T23:03:00.000Z", state: "held" as const },
    };
    const p = vetoPushPayload(c, "held", "2026-10-28T23:00:30.000Z", {});
    expect(p.command).not.toContain("abcdefghijklmnop");
    expect(p.command.length).toBe(200);
    expect(p.secondsLeft).toBe(150);
    expect(p.denyUrl).toBe("/auth/api/approvals/6f1c2b9e-3d4a-4e7b-9a51-0c2d8e7f1a23/deny");
    expect(vetoPushPayload(c, "held", "2026-10-28T23:00:30.000Z", { includeCommand: false }).command).toBe("");
  });

  it("sends ntfy JSON: payload in the message, a Deny tap to the approval page, no redirects", async () => {
    const calls: { url: string; init: RequestInit }[] = [];
