1	/**
2	 * lib-hub veto@1 (web) — held "veto" calls: a command the hub holds for a countdown and then runs itself, unless Brett
3	 * denies it first (Brett, Oct 28 2026: "instead of an Approve button I can Deny it and stop it from running before time
4	 * is up"). Additive to hub.ts: the approvals feed parser there is unchanged; this file reads the same reply again for
5	 * the held entries and splits them off, so an app shows held calls (countdown + Deny) apart from calls waiting for an
6	 * approval (Review).
7	 *
8	 * The contract (axHub decision 101 + veto@1):
9	 *  - the feed (`GET /auth/api/approvals`, legacy `/auth/admin/approvals.json`) lists a held call in `pending` with
10	 *    `status: "held"`, `veto: { runsAt, secondsLeft, countdownSeconds }`, `jobId`, `denyUrl`, `streamUrl`; also in
11	 *    `held[]` with `heldCount`;
12	 *  - Deny is `POST /auth/api/approvals/<id>/deny` (admin session + the hub's own Origin + `X-AxHub-CSRF`), so only a
13	 *    page on the hub (or the phone's native session) can send it; other apps open the approval page instead;
14	 *  - the job stream `GET /auth/api/jobs/<jobId>/stream` (SSE): `countdown {secondsLeft}`, `state {state}`,
15	 *    `output {stream, text}`, `done {state, exitCode}`;
16	 *  - pushes `{ type: "veto", phase: "held"|"warning"|"running", id, jobId, title, command, runsAt, secondsLeft, … }`;
17	 *  - states: held → running → ran | failed, or denied, or expired.
18	 *
19	 * Every link an app uses is rebuilt here from the ids (a link from the hub is used only to check it points at the hub),
20	 * the same rule as the approvals feed. Countdowns run on the local clock from `secondsLeft` (read time kept), so a phone
21	 * whose clock is off still counts down right; `runsAt` is the fallback.
22	 *
23	 * Kotlin twin: deferred (all Android framework work is on hold); the AmberX shell's Java `VetoAlerts` reads the same
24	 * fields. Gap recorded in spec/PORTING.md.
25	 */
26	import { approvalUrl, approvalsUrl, feedUrl, HUB_DEFAULT, HUB_FEED_MAX_ITEMS, HUB_FIELD_CAPS, HUB_MESSAGES, interpretFeed, isApprovalId, isHub, normalizeHub, readCapped, unreachableFeed, type HubFeed, type HubFetch } from './hub';
27	import { readSse, type SseFrame } from '../../core/sse';
28	
29	export const VETO_CONTRACT = 'veto@1';
30	/** "Time running out": the second notification fires this many seconds before the call runs. */
31	export const VETO_WARNING_SECONDS = 30;
32	/** The hub's default countdown (3 minutes). */
33	export const VETO_DEFAULT_COUNTDOWN = 180;
34	export const VETO_MAX_COUNTDOWN = 24 * 3600;
35	export const VETO_COMMAND_CAP = 2000;
36	export const VETO_OUTPUT_CAP = 4000;
37	
38	export type VetoState = 'held' | 'running' | 'ran' | 'failed' | 'denied' | 'expired';
39	export const VETO_STATES: readonly VetoState[] = ['held', 'running', 'ran', 'failed', 'denied', 'expired'];
40	export const VETO_FINAL: readonly VetoState[] = ['ran', 'failed', 'denied', 'expired'];
41	export const isVetoFinal = (s: VetoState) => VETO_FINAL.includes(s);
42	/** Notification phases: held (timer started), warning (≤ 30 s left), running (time is up, the hub runs it). */
43	export type VetoPhase = 'held' | 'warning' | 'running';
44	export const VETO_PHASES: readonly VetoPhase[] = ['held', 'warning', 'running'];
45	
46	const JOB_ID = /^[A-Za-z0-9_-]{1,80}$/;
47	export const isJobId = (id: unknown): id is string => typeof id === 'string' && JOB_ID.test(id);
48	
49	/** One held call. `url` is its approval page on the hub; `denyUrl`/`streamUrl` are rebuilt from the ids. */
50	export interface VetoCall {
51	  id: string;
52	  jobId: string | null;
53	  tool: string;
54	  title: string;
55	  command: string;
56	  summary: string;
57	  runsAt: string;
58	  /** seconds left when it was read (`readAt`, local ms) */
59	  secondsLeft: number;
60	  countdownSeconds: number;
61	  readAt: number;
62	  url: string;
63	  denyUrl: string;
64	  streamUrl: string | null;
65	}
66	
67	export const vetoDenyUrl = (base: string, id: unknown): string | null => (isApprovalId(id) ? `${base}/auth/api/approvals/${id}/deny` : null);
68	export const vetoStreamUrl = (base: string, jobId: unknown): string | null => (isJobId(jobId) ? `${base}/auth/api/jobs/${jobId}/stream` : null);
69	
70	const o = (v: unknown): Record<string, unknown> | null => (v && typeof v === 'object' && !Array.isArray(v) ? (v as Record<string, unknown>) : null);
71	const s = (r: Record<string, unknown> | null, k: string): string | null => (r && typeof r[k] === 'string' ? (r[k] as string) : null);
72	const n = (r: Record<string, unknown> | null, k: string): number | null => (r && typeof r[k] === 'number' && Number.isFinite(r[k]) ? (r[k] as number) : null);
73	const clampSec = (v: number) => Math.max(0, Math.min(VETO_MAX_COUNTDOWN, Math.round(v)));
74	
75	/** The command out of an entry: `command`, `args.command`, or the `"command":"…"` in the hub's summary. */
76	export function commandOf(p: Record<string, unknown>): string {
77	  const direct = s(p, 'command') ?? s(o(p.args), 'command') ?? s(o(p.arguments), 'command');
78	  if (direct) return direct.slice(0, VETO_COMMAND_CAP);
79	  const m = /"command":"((?:[^"\\]|\\.)*)"/.exec(s(p, 'summary') ?? '');
80	  return m ? m[1]!.replace(/\\"/g, '"').replace(/\\\\/g, '\\').slice(0, VETO_COMMAND_CAP) : '';
81	}
82	
83	/**
84	 * A held call from a feed entry, a `held[]` entry, the explain layer or a push; null when it isn't one (no real approval
85	 * id, a link pointing somewhere other than the hub, no veto timing). `now` is the local clock (ms) it was read at.
86	 */
87	export function vetoOf(base: string, raw: unknown, now: number = Date.now()): VetoCall | null {
88	  const p = o(raw);
89	  if (!p) return null;
90	  const id = s(p, 'id');
91	  const url = approvalUrl(base, id);
92	  const denyUrl = vetoDenyUrl(base, id);
93	  if (!id || !url || !denyUrl) return null;
94	  for (const k of ['url', 'approvalUrl', 'denyUrl', 'streamUrl']) if (typeof p[k] === 'string' && !isHub(base, p[k])) return null;
95	  const v = o(p.veto) ?? p; // a push carries runsAt/secondsLeft at the top
96	  const runsAt = (s(v, 'runsAt') ?? '').slice(0, HUB_FIELD_CAPS.time);
97	  const left = n(v, 'secondsLeft');
98	  const at = runsAt ? Date.parse(runsAt) : NaN;
99	  if (left === null && !Number.isFinite(at)) return null;
100	  const secondsLeft = clampSec(left ?? (at - now) / 1000);
101	  const countdownSeconds = clampSec(n(v, 'countdownSeconds') ?? Math.max(VETO_DEFAULT_COUNTDOWN, secondsLeft));
102	  const jobId = isJobId(p.jobId) ? (p.jobId as string) : null;
103	  const tool = (s(p, 'tool') ?? 'vps.run').slice(0, HUB_FIELD_CAPS.tool);
104	  const reason = o(p.reason);
105	  const title = (s(p, 'title') ?? s(reason, 'title') ?? tool).slice(0, 200);
106	  return {
107	    id, jobId, tool, title, command: commandOf(p), summary: (s(p, 'summary') ?? '').slice(0, HUB_FIELD_CAPS.summary),
108	    runsAt, secondsLeft, countdownSeconds, readAt: now, url, denyUrl, streamUrl: vetoStreamUrl(base, jobId),
109	  };
110	}
111	
112	/** Is a feed entry a held veto call (rather than a call waiting for an approval)? */
113	export const isHeldEntry = (raw: unknown): boolean => { const p = o(raw); return !!p && p.status === 'held' && !!o(p.veto); };
114	
115	/** Every held call in a feed reply body (`pending` entries with `status: "held"` and `held[]`), deduped, capped. */
116	export function interpretVeto(base: string, body: string, now: number = Date.now()): VetoCall[] {
117	  let j: Record<string, unknown> | null;
118	  try { j = o(JSON.parse(body)); } catch { return []; }
119	  if (!j) return [];
120	  const out: VetoCall[] = [];
121	  const ids = new Set<string>();
122	  const add = (raw: unknown) => {
123	    if (out.length >= HUB_FEED_MAX_ITEMS) return;
124	    const c = vetoOf(base, raw, now);
125	    if (c && !ids.has(c.id)) { ids.add(c.id); out.push(c); }
126	  };
127	  for (const e of Array.isArray(j.pending) ? j.pending : []) if (isHeldEntry(e)) add(e);
128	  for (const e of Array.isArray(j.held) ? j.held : []) add(e);
129	  return out.sort((a, b) => a.secondsLeft - b.secondsLeft);
130	}
131	
132	/** A feed split in two: calls waiting for an approval (`feed`, held ones taken out) and held veto calls. */
133	export interface VetoFeed { feed: HubFeed; held: VetoCall[] }
134	
135	export function splitFeed(base: string, status: number, body: string, now: number = Date.now()): VetoFeed {
136	  const feed = interpretFeed(base, status, body);
137	  if (feed.status !== 'ok') return { feed, held: [] };
138	  const held = interpretVeto(base, body, now);
139	  if (!held.length) return { feed, held };
140	  const heldIds = new Set(held.map((c) => c.id));
141	  const pending = feed.pending.filter((p) => !heldIds.has(p.id));
142	  return { feed: { ...feed, pending, count: Math.max(pending.length, feed.count - (feed.pending.length - pending.length)) }, held };
143	}
144	
145	/** Reads the approvals feed (same rules as `fetchHubFeed`: own session, redirects refused, capped) and splits it. */
146	export async function fetchVetoFeed(base: string, opts: { fetch?: HubFetch; now?: () => number; url?: string } = {}): Promise<VetoFeed> {
147	  const hub = normalizeHub(base);
148	  if (!hub) return { feed: unreachableFeed(HUB_DEFAULT), held: [] };
149	  const f: HubFetch = opts.fetch ?? ((u, i) => fetch(u, i));
150	  let r: Response;
151	  try {
152	    r = await f(opts.url ?? feedUrl(hub), { credentials: 'include', cache: 'no-store', redirect: 'error' });
153	  } catch (e) {
154	    return { feed: unreachableFeed(hub, ((e as Error)?.message || HUB_MESSAGES.unreachable).slice(0, 120)), held: [] };
155	  }
156	  if (r.type === 'opaqueredirect' || (r.status >= 300 && r.status < 400)) return { feed: interpretFeed(hub, r.status || 302, ''), held: [] };
157	  if (r.status !== 200) return { feed: interpretFeed(hub, r.status, ''), held: [] };
158	  let body: string | null;
159	  try { body = await readCapped(r); } catch (e) { return { feed: unreachableFeed(hub, ((e as Error)?.message || HUB_MESSAGES.unreachable).slice(0, 120)), held: [] }; }
160	  if (body === null) return { feed: unreachableFeed(hub, HUB_MESSAGES.tooLarge), held: [] };
161	  return splitFeed(hub, 200, body, (opts.now ?? Date.now)());
162	}
163	
164	/* ---------------------------------------------------------------- the countdown */
165	
166	/** Seconds left now, on the local clock from when it was read. */
167	export const secondsLeftNow = (c: Pick<VetoCall, 'secondsLeft' | 'readAt'>, now: number = Date.now()): number =>
168	  Math.max(0, Math.ceil(c.secondsLeft - (now - c.readAt) / 1000));
169	
170	export const vetoPhase = (secondsLeft: number): VetoPhase => (secondsLeft <= 0 ? 'running' : secondsLeft <= VETO_WARNING_SECONDS ? 'warning' : 'held');
171	
172	/** 2:59, 0:05 */
173	export const formatCountdown = (sec: number): string => {
174	  const t = Math.max(0, Math.floor(sec));
175	  return `${Math.floor(t / 60)}:${String(t % 60).padStart(2, '0')}`;
176	};
177	
178	/**
179	 * Which notifications to send now: for each held call, every phase it has reached that wasn't sent yet (`sent` holds
180	 * `<id>:<phase>`). A call first seen already in its warning time gets one notification for that phase, not two. Returns the
181	 * notifications and the new sent list (ids no longer held drop out, except those that reached running).
182	 */
183	export function notifyPlan(sent: readonly string[], calls: readonly VetoCall[], now: number = Date.now()): { send: { call: VetoCall; phase: VetoPhase }[]; sent: string[] } {
184	  const was = new Set(sent);
185	  const next = new Set<string>();
186	  const send: { call: VetoCall; phase: VetoPhase }[] = [];
187	  for (const c of calls) {
188	    const phase = vetoPhase(secondsLeftNow(c, now));
189	    const reached = VETO_PHASES.slice(0, VETO_PHASES.indexOf(phase) + 1);
190	    const fresh = reached.filter((p) => !was.has(`${c.id}:${p}`));
191	    reached.forEach((p) => next.add(`${c.id}:${p}`));
192	    if (fresh.length) send.push({ call: c, phase: fresh[fresh.length - 1]! });
193	  }
194	  return { send, sent: [...next].slice(-600) };
195	}
196	
197	/* ---------------------------------------------------------------- pushes */
198	
199	export interface VetoPush { phase: VetoPhase; call: VetoCall }
200	
201	/** A hub push `{type: "veto", phase, id, …}` → the call and its phase; null for anything else. */
202	export function vetoFromPush(base: string, raw: unknown, now: number = Date.now()): VetoPush | null {
203	  let p: unknown = raw;
204	  if (typeof raw === 'string') { try { p = JSON.parse(raw); } catch { return null; } }
205	  const j = o(p);
206	  if (!j || j.type !== 'veto' || !VETO_PHASES.includes(j.phase as VetoPhase)) return null;
207	  const call = vetoOf(base, j, now);
208	  return call ? { phase: j.phase as VetoPhase, call } : null;
209	}
210	
211	/* ---------------------------------------------------------------- the job stream */
212	
213	export type VetoEvent =
214	  | { type: 'countdown'; secondsLeft: number }
215	  | { type: 'state'; state: VetoState }
216	  | { type: 'output'; stream: 'stdout' | 'stderr'; text: string }
217	  | { type: 'done'; state: VetoState; exitCode: number | null };
218	
219	/** One SSE frame from the job stream → a typed event; null for anything unknown or malformed. */
220	export function vetoEvent(f: Pick<SseFrame, 'event' | 'data'>): VetoEvent | null {
221	  let d: Record<string, unknown> | null;
222	  try { d = o(JSON.parse(f.data)); } catch { return null; }
223	  if (!d) return null;
224	  const state = VETO_STATES.includes(d.state as VetoState) ? (d.state as VetoState) : null;
225	  switch (f.event) {
226	    case 'countdown': { const v = n(d, 'secondsLeft'); return v === null ? null : { type: 'countdown', secondsLeft: clampSec(v) }; }
227	    case 'state': return state ? { type: 'state', state } : null;
228	    case 'output': return { type: 'output', stream: d.stream === 'stderr' ? 'stderr' : 'stdout', text: (s(d, 'text') ?? '').slice(0, VETO_OUTPUT_CAP) };
229	    case 'done': { const code = n(d, 'exitCode'); return { type: 'done', state: state && isVetoFinal(state) ? state : code === 0 ? 'ran' : 'failed', exitCode: code === null ? null : Math.round(code) }; }
230	    default: return null;
231	  }
232	}
233	
234	/** Follows a held call's job stream to its end with the app's own hub session; resolves with how it ended (null = cut off). */
235	export async function followVeto(streamUrl: string, base: string, onEvent: (e: VetoEvent) => void, opts: { fetch?: HubFetch; signal?: AbortSignal } = {}): Promise<VetoState | null> {
236	  if (!isHub(base, streamUrl)) throw new Error('Not a hub stream.');
237	  const f: HubFetch = opts.fetch ?? ((u, i) => fetch(u, i));
238	  const r = await f(streamUrl, { credentials: 'include', cache: 'no-store', redirect: 'error', headers: { Accept: 'text/event-stream' }, signal: opts.signal });
239	  if (r.status !== 200) throw new Error(HUB_MESSAGES.answered.replace('{status}', String(r.status)));
240	  let end: VetoState | null = null;
241	  await readSse(r, (fr) => { const e = vetoEvent(fr); if (!e) return; if (e.type === 'done') end = e.state; onEvent(e); }, opts.signal);
242	  return end;
243	}
244	
245	/* ---------------------------------------------------------------- deny */
246	
247	/**
248	 * Denies a held call from a page on the hub's own origin (the AXHub web app): the session's CSRF value from
249	 * `/auth/api/session`, then `POST <denyUrl>`. Other origins can't (the hub checks Origin): they open `call.url`.
250	 */
251	export async function denyVeto(base: string, id: string, opts: { fetch?: HubFetch; csrf?: string } = {}): Promise<{ ok: boolean; state?: VetoState; error?: string }> {
252	  const url = vetoDenyUrl(base, id);
253	  if (!url) return { ok: false, error: 'Not an approval id.' };
254	  const f: HubFetch = opts.fetch ?? ((u, i) => fetch(u, i));
255	  try {
256	    let csrf = opts.csrf;
257	    if (!csrf) {
258	      const sr = await f(`${base}/auth/api/session`, { credentials: 'include', cache: 'no-store', redirect: 'error' });
259	      csrf = s(o(await sr.json().catch(() => null)), 'csrf') ?? undefined;
260	      if (!csrf) return { ok: false, error: 'Sign in to axHub to deny it.' };
261	    }
262	    const r = await f(url, { method: 'POST', credentials: 'include', cache: 'no-store', redirect: 'error', headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-AxHub-CSRF': csrf }, body: '{}' });
263	    const j = o(await r.json().catch(() => null));
264	    const state = VETO_STATES.includes(j?.state as VetoState) ? (j!.state as VetoState) : undefined;
265	    if (r.status === 200) return { ok: true, state: state ?? 'denied' };
266	    return { ok: false, state, error: s(o(j?.error), 'message') ?? HUB_MESSAGES.answered.replace('{status}', String(r.status)) };
267	  } catch (e) {
268	    return { ok: false, error: ((e as Error)?.message || HUB_MESSAGES.unreachable).slice(0, 120) };
269	  }
270	}
