  const what = c.command || c.tool;
  if (phase === 'held') return { title: `Runs in ${formatCountdown(secondsLeft)}: ${c.title}`, text: `${what}\nDeny to stop it.` };
  if (phase === 'warning') return { title: `${Math.max(0, Math.round(secondsLeft))} s left: ${c.title}`, text: `${what}\nDeny now to stop it.` };
  return { title: `Running now: ${c.title}`, text: what };
}

/** Browser stand-in for the phone's sounds: a short tone sequence per sound (frequency Hz, ms). */
export function tonesOf(sound: Sound): [number, number][] {
  switch (sound) {
    case 'alarm': return [[880, 180], [0, 80], [880, 180], [0, 80], [880, 180]];
    case 'ringtone': return [[660, 250], [830, 250], [660, 250]];
    case 'none': return [];
    default: return [[740, 200]];
  }
}
/**
 * Deny a held call (veto@1) and the store hook, shared by the plugin's settings and the Terminal view. The phone posts the
 * Deny with its hub session (hub Origin + CSRF, `VetoAlerts.deny`); a browser opens the call on the hub, the only origin
 * the hub takes a Deny from.
 */
import { useSyncExternalStore } from 'react';
import type { AxfRuntime } from '../../../axf/core';
import { isNative, native } from '../../../native';
import { checkVeto, markDenied, subscribeVeto, vetoState, type Track } from './store';
import type { ApprovalDecision, ApprovalItem, DecideResult } from '../../../axf/libs/approvals';

let runtime: AxfRuntime | null = null;
export const setRuntime = (rt: AxfRuntime) => { runtime = rt; };
export const getRuntime = () => runtime;

export const useVeto = () => useSyncExternalStore(subscribeVeto, vetoState, vetoState);

export async function deny(t: Track): Promise<void> {
  const rt = runtime;
  if (isNative()) {
    const r = await native.vetoDeny({ id: t.call.id }).catch((e) => ({ ok: false, error: String(e?.message ?? e) }));
    if (r.ok) { markDenied(t.call.id); rt?.toast(`Denied: ${t.call.title}`, 'success', 'Approvals'); void checkVeto(); return; }
    rt?.toast(`Couldn't deny it here (${r.error ?? 'hub refused'}). Opening it on the hub.`, 'warning', 'Approvals');
    void native.hubOpen({ url: t.call.url }).finally(() => void checkVeto());
    return;
  }
  window.open(t.call.url, '_blank', 'noopener,noreferrer');
}

/**
 * lib-approvals' deciding path on the phone (the assistant title bar badge): Deny a held call with the phone's hub
 * session (native `vetoDeny`, the same as the notification's Deny), falling back to its page; Approve / Decline open the
 * approval in the signed-in hub web view (Approve is on its first screen), the way AmberX decides approvals everywhere.
 * In a browser `native.hubOpen` opens the hub page. The badge's toast comes when the item leaves the feed.
 */
export async function decideFromPhone(item: ApprovalItem, d: ApprovalDecision): Promise<DecideResult> {
  if (d === 'deny' && isNative()) {
    const r = await native.vetoDeny({ id: item.id }).catch((e) => ({ ok: false, error: String(e?.message ?? e) }));
    if (r.ok) { markDenied(item.id); void checkVeto(); return { ok: true, message: `Denied: ${item.title}` }; }
    runtime?.toast(`Couldn't deny it here (${r.error ?? 'hub refused'}). Opening it on the hub.`, 'warning', 'Approvals');
  }
  await native.hubOpen({ url: item.url }).catch(() => undefined);
  void checkVeto();
  return { ok: true, opened: true, message: '' };
}
/**
 * Veto approvals store: what the hub holds right now, one track per held call (countdown, state, output), shared by the
 * notifications, the Approvals page and the Terminal view.
 *
 * Reads the hub's approvals feed every 5 s while AmberX is on screen (and on focus) with lib-hub's `fetchVetoFeed`, and
 * follows each held call's job stream (`followVeto`: countdown, state, output, done) from the moment its timer is seen
 * until it ends. The countdown ticks on the local clock between reads. With the app closed, the Android watch service
 * (`VetoAlerts.java`) raises the same notifications from the same feed.
 */
import { followVeto, fetchVetoFeed, isVetoFinal, secondsLeftNow, type VetoCall, type VetoEvent, type VetoState } from '../../../axf/libs/hub/veto';
import type { HubFeedStatus } from '../../../axf/libs/hub';
import { HUB } from '../../../hub/useHub';

export const POLL_MS = 5_000;
export const LINES_MAX = 500;
/** Finished tracks kept (as terminal tabs) until closed. */
export const KEEP_MAX = 20;

export type TrackState = VetoState | 'gone';
export interface TermLine { at: number; stream: 'stdout' | 'stderr' | 'note'; text: string }
export interface Track {
  call: VetoCall;
  state: TrackState;
  /** seconds left now (ticks locally; stream countdown events correct it) */
  left: number;
  exitCode: number | null;
  lines: TermLine[];
  streaming: boolean;
  startedAt: number;
}

interface State { status: 'idle' | HubFeedStatus; held: VetoCall[]; tracks: Track[]; checkedAt: number | null }
let st: State = { status: 'idle', held: [], tracks: [], checkedAt: null };
const subs = new Set<() => void>();
const emit = () => subs.forEach((f) => f());
export const vetoState = () => st;
export const subscribeVeto = (f: () => void) => { subs.add(f); return () => { subs.delete(f); }; };

type Hooks = { started?: (t: Track) => void; changed?: (t: Track, from: TrackState) => void };
let hooks: Hooks = {};
export const setVetoHooks = (h: Hooks) => { hooks = h; };

const streams = new Map<string, AbortController>();

function patch(id: string, f: (t: Track) => Track) {
  const i = st.tracks.findIndex((t) => t.call.id === id);
  if (i < 0) return;
  const before = st.tracks[i]!;
  const after = f(before);
  const tracks = [...st.tracks];
  tracks[i] = after;
  st = { ...st, tracks };
  if (after.state !== before.state) hooks.changed?.(after, before.state);
  emit();
}

const line = (stream: TermLine['stream'], text: string): TermLine => ({ at: Date.now(), stream, text });
const addLines = (t: Track, more: TermLine[]): Track => ({ ...t, lines: [...t.lines, ...more].slice(-LINES_MAX) });

function onEvent(id: string, e: VetoEvent) {
  patch(id, (t) => {
    switch (e.type) {
      case 'countdown': return { ...t, left: e.secondsLeft, call: { ...t.call, secondsLeft: e.secondsLeft, readAt: Date.now() } };
      case 'state': return addLines({ ...t, state: e.state, left: e.state === 'held' ? t.left : 0 }, [line('note', stateNote(e.state))]);
      case 'output': return addLines(t, e.text.split('\n').filter((x, i, a) => x || i < a.length - 1).map((x) => line(e.stream, x)));
      case 'done': return addLines({ ...t, state: e.state, exitCode: e.exitCode, left: 0 }, [line('note', `${stateNote(e.state)}${e.exitCode === null ? '' : ` (exit ${e.exitCode})`}`)]);
    }
  });
}

export const stateNote = (s: TrackState): string => ({
  held: 'Held: runs when the countdown ends unless you deny it.',
  running: 'Running now.',
  ran: 'Ran.',
  failed: 'Failed.',
  denied: 'Denied: it did not run.',
  expired: 'Expired: it did not run.',
  gone: 'No longer held on the hub (decided there, or the hub restarted). See the hub for how it ended.',
} as Record<TrackState, string>)[s];

/** Follow a held call's job stream until it ends; retried a few times when cut off. */
async function follow(id: string) {
  const t = st.tracks.find((x) => x.call.id === id);
  if (!t?.call.streamUrl || streams.has(id)) return;
  const ctl = new AbortController();
  streams.set(id, ctl);
  patch(id, (x) => ({ ...x, streaming: true }));
  let tries = 0;
  try {
    while (!ctl.signal.aborted && tries < 5) {
      try {
        const end = await followVeto(t.call.streamUrl, HUB, (e) => onEvent(id, e), { signal: ctl.signal });
        if (end) break;
      } catch (e) {
        if (ctl.signal.aborted) break;
        if (tries === 0) patch(id, (x) => addLines(x, [line('note', `Live output unavailable (${String((e as Error)?.message ?? e)}); retrying.`)]));
      }
      const now = st.tracks.find((x) => x.call.id === id);
      if (!now || isFinal(now.state)) break;
      tries += 1;
      await new Promise((r) => setTimeout(r, 2_000 * tries));
    }
  } finally {
    streams.delete(id);
    patch(id, (x) => ({ ...x, streaming: false }));
  }
}

export const isFinal = (s: TrackState) => s === 'gone' || isVetoFinal(s as VetoState);

/** Merge a fresh list of held calls: new ones start a track (and their stream), missing ones end theirs. */
export function mergeHeld(held: VetoCall[], now: number = Date.now()) {
  const ids = new Set(held.map((c) => c.id));
  let tracks = [...st.tracks];
  const started: Track[] = [];
  for (const c of held) {
    const i = tracks.findIndex((t) => t.call.id === c.id);
    if (i < 0) {
      const t: Track = { call: c, state: 'held', left: secondsLeftNow(c, now), exitCode: null, lines: [line('note', `Held: ${c.title}`), line('note', `$ ${c.command || c.tool}`)], streaming: false, startedAt: now };
      tracks.push(t);
      started.push(t);
    } else if (tracks[i]!.state === 'held') {
      tracks[i] = { ...tracks[i]!, call: c, left: secondsLeftNow(c, now) };
    }
  }
  // A held track the hub no longer lists: if its stream isn't telling us how it ended, say so.
  const gone: string[] = [];
  tracks = tracks.map((t) => {
    if (t.state !== 'held' || ids.has(t.call.id) || streams.has(t.call.id)) return t;
    gone.push(t.call.id);
    const note = t.left > 0 ? stateNote('gone') : 'Time was up: the hub ran it. Live output is not available here; see the hub for the result.';
    return addLines({ ...t, state: 'gone' as TrackState, left: 0 }, [line('note', note)]);
  });
  const done = tracks.filter((t) => isFinal(t.state));
  if (done.length > KEEP_MAX) { const drop = new Set(done.slice(0, done.length - KEEP_MAX).map((t) => t.call.id)); tracks = tracks.filter((t) => !drop.has(t.call.id)); }
  st = { ...st, held, tracks };
  for (const t of started) { hooks.started?.(t); void follow(t.call.id); }
  for (const id of gone) { const t = tracks.find((x) => x.call.id === id); if (t) hooks.changed?.(t, 'held'); }
  emit();
}

/** Every second: count down held tracks; at zero a held track shows "running" until the stream (or the feed) says more. */
function tick() {
  const now = Date.now();
  let changed = false;
  const tracks = st.tracks.map((t) => {
    if (t.state !== 'held') return t;
    const left = secondsLeftNow(t.call, now);
    if (left === t.left) return t;
    changed = true;
    return { ...t, left };
  });
  if (changed) { st = { ...st, tracks }; emit(); }
}

let inflight = false;
export async function checkVeto(): Promise<void> {
  if (inflight) return;
  inflight = true;
  try {
    const r = await fetchVetoFeed(HUB);
    st = { ...st, status: r.feed.status, checkedAt: Date.now() };
    if (r.feed.status === 'ok') mergeHeld(r.held); else emit();
  } finally { inflight = false; }
}

let started = false;
export function startVeto() {
  if (started || typeof document === 'undefined') return;
  started = true;
  void checkVeto();
  setInterval(() => { if (document.visibilityState === 'visible') void checkVeto(); }, POLL_MS);
  setInterval(tick, 1_000);
  globalThis.addEventListener?.('focus', () => void checkVeto());
  document.addEventListener('visibilitychange', () => { if (document.visibilityState === 'visible') void checkVeto(); });
}

/** Mark a track denied locally (the stream or the next read confirms). */
export function markDenied(id: string) {
  patch(id, (t) => (t.state === 'held' ? addLines({ ...t, state: 'denied', left: 0 }, [line('note', stateNote('denied'))]) : t));
  streams.get(id)?.abort();
}

export function closeTrack(id: string) {
  streams.get(id)?.abort();
  st = { ...st, tracks: st.tracks.filter((t) => t.call.id !== id || !isFinal(t.state)) };
  emit();
}

/** Tests only. */
export function resetVeto() { streams.forEach((c) => c.abort()); streams.clear(); st = { status: 'idle', held: [], tracks: [], checkedAt: null }; emit(); }

content.content:
/**
 * Veto approvals (Brett, Oct 28 2026): Claude sends a command to the VPS through Vinnie on axHub; the hub holds it for a
 * 3-minute countdown and then runs it itself, unless Brett denies it first. AmberX tells him: a notification when the
 * timer starts (title, the command, a Deny action), a second when time is running out (30 s left) and a third when it
 * starts running, each with its own sound, plus the vibration he picks (Settings → Plugins → Approvals, each with Test).
 *
 * On Android the notifications come from the watch service (`VetoAlerts.java`: channels with the chosen sound and
 * vibration, Deny posted with the phone's hub session under the hub's Origin + CSRF, the same way auto-approval posts).
 * In a browser this page raises them while it is open (Notification API, tones, `navigator.vibrate`) and Deny opens the
 * call on the hub, which only takes a Deny under its own Origin.
 *
 * It also plugs the phone's deciding path into lib-approvals (the assistant title bar badge): native Deny, Approve /
 * Decline in the signed-in hub web view.
 *
 * Removable: everything is in this folder except the shell's `VetoAlerts.java` + its seam in native.ts (shared shell
 * code, like the monitor's WatchService). Uninstall: `node framework/cli/plugin-catalog.mjs app-uninstall amberx approvals`.
 */
import { useEffect, useState } from 'react';
import { Button, Note, Section, useRuntime, type AxfWebLibrary } from '../../../axf/react';
import { notifyPlan, secondsLeftNow, type VetoPhase } from '../../../axf/libs/hub/veto';
import { isNative, native } from '../../../native';
import { alertConfig, DEFAULTS, K, notificationText, patternOf, SOUNDS, soundOf, tonesOf, VIBRATIONS, vibrationOf, type Sound } from './core';
import { checkVeto, markDenied, startVeto, subscribeVeto, vetoState, setVetoHooks } from './store';
import { decideFromPhone, deny, getRuntime, setRuntime, useVeto } from './deny';
import { setApprovalsHost } from '../../../axf/libs/approvals/react';
import { HUB } from '../../../hub/useHub';
import { showTab, TerminalView } from './terminal';

const ID = 'ai.amberx.amberx.approvals';
const SENT_KEY = 'amberx.approvals.sent';

/* ---------------------------------------------------------------- sounds (browser) */

let audio: AudioContext | null = null;
export function playTones(sound: Sound) {
  const seq = tonesOf(sound);
  if (!seq.length) return;
  try {
    audio ??= new AudioContext();
    let at = audio.currentTime;
    for (const [hz, ms] of seq) {
      if (hz > 0) {
        const o = audio.createOscillator();
        const g = audio.createGain();
        o.frequency.value = hz;
        g.gain.setValueAtTime(0.18, at);
        g.gain.exponentialRampToValueAtTime(0.001, at + ms / 1000);
        o.connect(g).connect(audio.destination);
        o.start(at);
        o.stop(at + ms / 1000);
      }
      at += ms / 1000;
    }
  } catch { /* no audio */ }
}

const get = (k: string) => getRuntime()?.settings.get(k);

/** One phase's notification: native channel test, or the browser's tones + vibration + a Notification. */
export function testPhase(phase: VetoPhase) {
  if (isNative()) { void native.vetoTest({ phase }).catch(() => undefined); return; }
  const cfg = alertConfig(get)[phase];
  playTones(cfg.sound);
  if (cfg.vibrate && cfg.vibration.length) try { navigator.vibrate?.(cfg.vibration); } catch { /* none */ }
  const { title, text } = notificationText({ title: 'Test call', command: 'echo hello', tool: 'vps.run' }, phase, phase === 'held' ? 180 : phase === 'warning' ? 30 : 0);
  try { if (typeof Notification !== 'undefined' && Notification.permission === 'granted') new Notification(title, { body: text, tag: `veto-test-${phase}` }); } catch { /* none */ }
}

/* ---------------------------------------------------------------- browser notifications */

const loadSent = (): string[] => { try { return JSON.parse(localStorage.getItem(SENT_KEY) ?? '[]') as string[]; } catch { return []; } };
const saveSent = (v: string[]) => { try { localStorage.setItem(SENT_KEY, JSON.stringify(v)); } catch { /* fine */ } };

function notifyInPage() {
  const s = vetoState();
  if (s.status !== 'ok') return;
  const plan = notifyPlan(loadSent(), s.tracks.filter((t) => t.state === 'held').map((t) => t.call));
  saveSent(plan.sent);
  if (!plan.send.length || typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  const cfg = alertConfig(get);
  for (const { call, phase } of plan.send) {
    const { title, text } = notificationText(call, phase, secondsLeftNow(call));
    playTones(cfg[phase].sound);
    if (cfg[phase].vibrate && cfg[phase].vibration.length) try { navigator.vibrate?.(cfg[phase].vibration); } catch { /* none */ }
    const n = new Notification(title, { body: text, tag: `veto-${call.id}`, requireInteraction: phase !== 'running' });
    n.onclick = () => { window.focus(); getRuntime()?.dispatch(`approvals.terminal:${call.id}`); };
  }
}

/* ---------------------------------------------------------------- settings */

function TestRow() {
  return (
    <div className="fx-row fx-row--wrap">
      <Button icon="bell" onClick={() => testPhase('held')}>Test timer started</Button>
      <Button icon="clock" onClick={() => testPhase('warning')}>Test time running out</Button>
      <Button icon="play" onClick={() => testPhase('running')}>Test running</Button>
    </div>
  );
}

function StatusPanel() {
  const s = useVeto();
  const rt = useRuntime();
  useEffect(() => { startVeto(); }, []);
  const held = s.tracks.filter((t) => t.state === 'held');
  return (
    <div className="fx-stack">
      <p style={{ margin: 0 }}>
        Commands Claude sends to the VPS through Vinnie wait 3 minutes before the hub runs them. AmberX notifies you when the
        timer starts, again with 30 seconds left, and when it runs. There is no Approve: tap Deny to stop one before time is up.
      </p>
      <p className="fx-small" style={{ margin: 0 }}>
        <strong>{s.status === 'ok' ? (held.length ? `${held.length} held now.` : 'Nothing held.') : s.status === 'idle' ? 'Checking…' : s.status === 'signed-out' ? 'Sign in to axHub to see held calls.' : s.status === 'not-admin' ? 'Held calls are for hub admins.' : "Can't reach axHub."}</strong>
        {isNative() ? <span className="fx-muted"> · with the app closed, the watch service (Monitor) sends them</span> : <span className="fx-muted"> · in a browser, only while this tab is open</span>}
      </p>
      <TestRow />
      <div className="fx-row fx-row--wrap">
        <Button icon="terminal" onClick={() => rt.dispatch('approvals.terminal')}>Open the terminal</Button>
        <Button icon="refresh" onClick={() => void checkVeto()}>Check now</Button>
      </div>
    </div>
  );
}

function PermissionNote() {
  const [perm, setPerm] = useState(typeof Notification === 'undefined' ? 'unsupported' : Notification.permission);
  if (isNative() || perm === 'granted' || perm === 'unsupported') return null;
  return (
    <Note tone="warning">
      Notifications are off for this site. <Button size="sm" onClick={() => void Notification.requestPermission().then(setPerm)}>Allow notifications</Button>
    </Note>
  );
}

/* ---------------------------------------------------------------- library */

export const library: AxfWebLibrary = {
  id: ID,
  label: 'Approvals (veto)',
  version: '0.1.1',
  builtWith: { model: 'opus', builtAt: '2026-10-28' },
  provides: ['amberx.approvals.veto', 'amberx.terminal'],
  views: { terminal: { title: 'Terminal', icon: 'terminal', keywords: ['terminal', 'held', 'veto', 'deny', 'countdown', 'command', 'output'], render: () => <TerminalView /> } },
  nav: { label: 'Terminal', items: [{ id: 'terminal', label: 'Terminal', icon: 'terminal', view: 'terminal' }] },
  settingsTabs: [{ id: 'approvals', label: 'Approvals', icon: 'shield', order: 20, parent: 'plugins' }],
  settings: [
    {
      id: 'amberx.approvals.alerts', label: 'Held call notifications', icon: 'bell', tab: 'approvals', order: 2,
      description: 'Sounds and vibration for the three notifications of a held command. On Android each is its own notification channel.',
      settings: [
        { key: K.sound, label: 'Timer started sound', kind: 'choice', default: DEFAULTS.sound, options: SOUNDS.map(({ value, label }) => ({ value, label })) },
        { key: K.vibration, label: 'Vibration', kind: 'choice', default: DEFAULTS.vibration, options: VIBRATIONS.map(({ value, label }) => ({ value, label })) },
        { key: K.warningSound, label: 'Time running out sound (30 s left)', kind: 'choice', default: DEFAULTS.warningSound, options: SOUNDS.map(({ value, label }) => ({ value, label })) },
        { key: K.runningSound, label: 'Running sound', kind: 'choice', default: DEFAULTS.runningSound, options: SOUNDS.map(({ value, label }) => ({ value, label })) },
        { key: K.openTerminal, label: 'Open a terminal tab when a timer starts', kind: 'toggle', default: true, description: 'The tab shows the command, the countdown and Deny, then the output when it runs.' },
      ],
    },
  ],
  settingsPanels: [
    { id: 'amberx.approvals.status', tab: 'approvals', title: 'Held commands', icon: 'shield', order: 1, render: () => <StatusPanel /> },
    { id: 'amberx.approvals.test', tab: 'approvals', title: 'Test the notifications', icon: 'bell', order: 3, render: () => <><PermissionNote /><Section title="Plays each one with the sound and vibration chosen above"><TestRow /></Section></> },
  ],
  register(rt) {
    setRuntime(rt);
    startVeto();
    // lib-approvals (assistant title bars): this app's hub, no framing (the hub frames only the console), and the
    // phone's deciding path. Removing this plugin leaves the badge on its defaults (hub pages open in the hub view).
    setApprovalsHost({ hub: HUB, frame: false, decide: decideFromPhone, open: (url) => void native.hubOpen({ url }).catch(() => undefined) });
    // Browser: notifications from this page. Android: the watch service sends them (also with the app closed).
    if (!isNative()) subscribeVeto(notifyInPage);
    setVetoHooks({
      started: (t) => { if (rt.settings.get(K.openTerminal) !== false) rt.dispatch(`approvals.terminal:${t.call.id}`); },
    });
    rt.actions.register('approvals.deny', ([id]) => {
      const t = vetoState().tracks.find((x) => x.call.id === id);
      if (t && t.state === 'held') void deny(t); else rt.toast('That call is no longer held.', 'info', 'Approvals');
    }, { label: 'Deny a held command', params: true, searchable: false });
    // approvals.terminal[:<id>] — the Terminal view, with that held command's tab in front
    rt.actions.register('approvals.terminal', ([id]) => { showTab(id ?? null); rt.navigate('terminal'); }, { label: 'Open the terminal', params: true });
    rt.actions.register('approvals.check', () => void checkVeto(), { label: 'Check held commands' });
    // Notification taps and Denies from the shell.
    void native.addListener('veto', (e) => {
      if (e.action === 'open') rt.dispatch(`approvals.terminal:${e.id}`);
      else if (e.action === 'denied') { markDenied(e.id); rt.toast('Denied from the notification.', 'success', 'Approvals'); }
      else rt.toast(`Deny from the notification failed${e.error ? ` (${e.error})` : ''}: open it on the hub.`, 'danger', 'Approvals');
      void checkVeto();
    }).catch(() => undefined);
    // The shell's channels follow the chosen sounds and vibration (same config = no call).
    let last = '';
    const sync = () => {
      const cfg = alertConfig((k) => rt.settings.get(k));
      const next = JSON.stringify(cfg);
      if (next === last) return;
      last = next;
      if (isNative()) void native.vetoSettings(cfg).catch(() => undefined);
    };
    rt.subscribe(sync);
    sync();
  },
};

export { soundOf, vibrationOf, patternOf, deny, useVeto };
/**
 * The AmberX Terminal: one tab per held command (veto@1). When a timer starts a tab opens with the title, the command,
 * a live countdown and Deny; at zero it shows the command running and its output lines from the hub's job stream; the tab
 * stays with how it ended (ran / failed / denied / expired) until closed.
 *
 * The console's Terminal plugin (`apps/console-web/plugins/console-terminal`) is a shell on the console's server (PTY over
 * its own API), so it can't run in AmberX: the command here runs on the hub (Vinnie), and AmberX only shows it. Built from
 * the framework's tabs (`fx-tabs`/`fx-tab`), terminal rows (`fx-terminal__*`), Button and Chip; layout CSS only.
 */
import { useEffect, useMemo, useState } from 'react';
import { Button, Chip, Icon, Note } from '../../../axf/react';
import { formatCountdown, VETO_WARNING_SECONDS } from '../../../axf/libs/hub/veto';
import { checkVeto, closeTrack, isFinal, startVeto, type Track, type TrackState } from './store';
import { deny, useVeto } from './deny';
import './terminal.css';

let wanted: string | null = null;
const listeners = new Set<(id: string) => void>();
/** Bring a tab to the front (approvals.terminal:<id>). */
export function showTab(id: string | null) { wanted = id; if (id) listeners.forEach((f) => f(id)); }

const TONE: Record<TrackState, 'accent' | 'success' | 'warning' | 'danger' | undefined> = {
  held: 'warning', running: 'accent', ran: 'success', failed: 'danger', denied: undefined, expired: undefined, gone: undefined,
};
export const label = (t: Track): string => (t.state === 'held' ? (t.left > 0 ? formatCountdown(t.left) : 'running…') : t.state === 'gone' ? 'left the hold' : t.state);

function TrackView({ t }: { t: Track }) {
  const [busy, setBusy] = useState(false);
  const held = t.state === 'held' && t.left > 0;
  const urgent = held && t.left <= VETO_WARNING_SECONDS;
  return (
    <div className="axp-veto-track">
      <div className="axp-veto-head">
        <div className="axp-veto-what">
          <strong className="axp-veto-title">{t.call.title}</strong>
          <code className="axp-veto-cmd">$ {t.call.command || t.call.tool}</code>
        </div>
        <div className="axp-veto-side">
          {held
            ? <span className={`axp-veto-count${urgent ? ' is-urgent' : ''}`} role="timer" aria-live={urgent ? 'assertive' : 'off'}>{formatCountdown(t.left)}</span>
            : <Chip tone={TONE[t.state]}>{label(t)}{t.exitCode !== null ? ` · exit ${t.exitCode}` : ''}</Chip>}
          {held && <Button tone="danger" icon="x-circle" busy={busy} onClick={() => { setBusy(true); void deny(t).finally(() => setBusy(false)); }}>Deny</Button>}
          <Button icon="external" onClick={() => window.open(t.call.url, '_blank', 'noopener,noreferrer')}>On the hub</Button>
        </div>
      </div>
