30	 * vibration chosen in AmberX (Settings → Plugins → Approvals; `vetoSettings` from the web side). Android channels can't
31	 * change once made, so a new choice makes a new channel (`veto_<phase>_<hash>`) and the old one is deleted.
32	 *
33	 * Deny (the notification action, or the app's Deny button through the plugin) posts `/auth/api/approvals/<id>/deny` with
34	 * the phone's hub session under the hub's Origin + CSRF ([HubRules#deny]), the same way auto-approval posts. A held call is
35	 * never auto-approved and never shown as an approval ([HubRules#interpret] skips it).
36	 */
37	final class VetoAlerts {
38	    private VetoAlerts() {}
39	
40	    static final String PREFS = "amberx_veto";
41	    static final String ACTION_DENY = "ai.amberx.droid.VETO_DENY";
42	    static final String EXTRA_ID = "ai.amberx.droid.VETO_ID";
43	    static final String[] PHASES = { "held", "warning", "running" };
44	    private static final String TAG = "veto:";
45	
46	    static SharedPreferences prefs(Context c) { return c.getSharedPreferences(PREFS, Context.MODE_PRIVATE); }
47	
48	    /* ---------------------------------------------------------------- channels (sound + vibration per phase) */
49	
50	    static JSONObject config(Context c) {
51	        try { return new JSONObject(prefs(c).getString("config", "{}")); } catch (Exception e) { return new JSONObject(); }
52	    }
53	
54	    /** Saves the alert config from the web side ({held, warning, running}: {sound, vibration[], vibrate}) and remakes channels. */
55	    static void configure(Context c, JSONObject cfg) {
56	        prefs(c).edit().putString("config", cfg == null ? "{}" : cfg.toString()).apply();
57	        channels(c);
58	    }
59	
60	    private static JSONObject phaseCfg(Context c, String phase) {
61	        JSONObject p = config(c).optJSONObject(phase);
62	        if (p != null) return p;
63	        JSONObject d = new JSONObject();
64	        try {
65	            d.put("sound", "running".equals(phase) ? "default" : "alarm").put("vibrate", true)
66	                .put("vibration", new JSONArray(new long[] { 0, 150, 100, 150, 100, 150 }));
67	        } catch (Exception ignored) {}
68	        return d;
69	    }
70	
71	    static Uri soundUri(String sound) {
72	        switch (sound == null ? "" : sound) {
73	            case "alarm": return Settings.System.DEFAULT_ALARM_ALERT_URI;
74	            case "ringtone": return Settings.System.DEFAULT_RINGTONE_URI;
75	            case "none": return null;
76	            default: return Settings.System.DEFAULT_NOTIFICATION_URI;
77	        }
78	    }
79	
80	    static long[] pattern(JSONObject p) {
81	        JSONArray a = p.optJSONArray("vibration");
82	        if (a == null || a.length() == 0) return null;
83	        long[] out = new long[Math.min(a.length(), 20)];
84	        for (int i = 0; i < out.length; i++) out[i] = Math.max(0, Math.min(5000, a.optLong(i, 0)));
85	        return out;
86	    }
87	
88	    static String channelId(Context c, String phase) {
89	        JSONObject p = phaseCfg(c, phase);
90	        String key = p.optString("sound", "default") + "|" + p.optBoolean("vibrate", true) + "|" + String.valueOf(p.optJSONArray("vibration"));
91	        return "veto_" + phase + "_" + Integer.toHexString(key.hashCode());
92	    }
93	
94	    static void channels(Context c) {
95	        if (Build.VERSION.SDK_INT < 26) return;
96	        NotificationManager nm = c.getSystemService(NotificationManager.class);
97	        Set<String> keep = new HashSet<>();
98	        for (String phase : PHASES) {
99	            JSONObject p = phaseCfg(c, phase);
100	            String id = channelId(c, phase);
101	            keep.add(id);
102	            if (nm.getNotificationChannel(id) != null) continue;
103	            String name = "held".equals(phase) ? "Held command: timer started" : "warning".equals(phase) ? "Held command: time running out" : "Held command: running";
104	            NotificationChannel ch = new NotificationChannel(id, name, NotificationManager.IMPORTANCE_HIGH);
105	            Uri sound = soundUri(p.optString("sound", "default"));
106	            AudioAttributes attrs = new AudioAttributes.Builder()
107	                .setUsage("alarm".equals(p.optString("sound")) ? AudioAttributes.USAGE_ALARM : AudioAttributes.USAGE_NOTIFICATION)
108	                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).build();
109	            ch.setSound(sound, sound == null ? null : attrs);
110	            boolean vibrate = p.optBoolean("vibrate", true);
111	            ch.enableVibration(vibrate);
112	            long[] pat = pattern(p);
113	            if (vibrate && pat != null) ch.setVibrationPattern(pat);
114	            nm.createNotificationChannel(ch);
115	        }
116	        for (NotificationChannel ch : nm.getNotificationChannels()) {
117	            if (ch.getId().startsWith("veto_") && !keep.contains(ch.getId())) nm.deleteNotificationChannel(ch.getId());
118	        }
119	    }
120	
121	    /* ---------------------------------------------------------------- the feed → notifications */
122	
123	    private static Set<String> sent(Context c) { return new HashSet<>(prefs(c).getStringSet("sent", new HashSet<>())); }
124	
125	    /**
126	     * Called by the watch service with every feed read: notifies phases reached and not sent yet, schedules the warning and
127	     * running ones on [work] at the local times they fall due, and takes cards away for calls the hub no longer holds
128	     * (denied or expired elsewhere). A call gone right when its time was up is shown as running.
129	     */
130	    static void update(Context c, Handler work, List<HubRules.Veto> held) {
131	        long now = System.currentTimeMillis();
132	        Set<String> was = sent(c);
133	        Set<String> next = new HashSet<>();
134	        Set<String> ids = new HashSet<>();
135	        NotificationManager nm = c.getSystemService(NotificationManager.class);
136	        channels(c);
137	        for (HubRules.Veto v : held) {
138	            ids.add(v.id);
139	            work.removeCallbacksAndMessages(token(v.id));
140	            int left = (int) Math.max(0, Math.ceil((v.runsAtLocal() - now) / 1000.0));
141	            String phase = HubRules.vetoPhase(left);
142	            if (was.contains(v.id + ":denied")) { next.add(v.id + ":denied"); continue; }
143	            String fresh = null;
144	            for (String p : PHASES) {
145	                if (rank(p) > rank(phase)) break;
146	                next.add(v.id + ":" + p);
147	                if (!was.contains(v.id + ":" + p)) fresh = p; // first seen late: one card for the phase it's in
148	            }
149	            if (fresh != null) nm.notify(TAG + v.id, 0, card(c, v, fresh));
150	            if (rank(phase) < rank("warning")) schedule(c, work, v, "warning", v.runsAtLocal() - HubRules.VETO_WARNING_SECONDS * 1000L - now);
151	            if (rank(phase) < rank("running")) schedule(c, work, v, "running", v.runsAtLocal() - now);
152	            JSONObject seen = known(c);
153	            try { seen.put(v.id, new JSONObject().put("title", v.title).put("command", v.command).put("url", v.url).put("runsAt", v.runsAtLocal())); } catch (Exception ignored) {}
154	            prefs(c).edit().putString("known", seen.toString()).apply();
155	        }
156	        // Calls no longer held: their timers stop; their card goes, unless their time was up (then it ran).
157	        JSONObject known = known(c);
158	        Set<String> gone = new HashSet<>();
159	        for (String key : was) {
160	            String id = key.substring(0, key.lastIndexOf(':'));
161	            if (!ids.contains(id)) gone.add(id);
162	        }
163	        for (String id : gone) {
164	            work.removeCallbacksAndMessages(token(id));
165	            JSONObject k = known.optJSONObject(id);
166	            boolean due = k != null && k.optLong("runsAt", Long.MAX_VALUE) - 3000 <= now && !was.contains(id + ":denied");
167	            if (due && !was.contains(id + ":running")) {
168	                HubRules.Veto v = new HubRules.Veto(id, null, "vps.run", k.optString("title"), k.optString("command"), k.optString("url"), 0, now);
169	                nm.notify(TAG + id, 0, card(c, v, "running"));
170	            } else if (!due) nm.cancel(TAG + id, 0);
171	            known.remove(id);
172	        }
173	        prefs(c).edit().putStringSet("sent", next).putString("known", known.toString()).apply();
174	    }
175	
176	    private static JSONObject known(Context c) {
177	        try { return new JSONObject(prefs(c).getString("known", "{}")); } catch (Exception e) { return new JSONObject(); }
178	    }
179	
180	    /** Handler tokens compare by identity: one interned string per call. */
181	    static String token(String id) { return (TAG + id).intern(); }
182	
183	    private static int rank(String phase) { return "held".equals(phase) ? 0 : "warning".equals(phase) ? 1 : 2; }
184	
185	    private static void schedule(Context c, Handler work, HubRules.Veto v, String phase, long delayMs) {
186	        Context app = c.getApplicationContext();
187	        work.postAtTime(() -> {
188	            Set<String> s = sent(app);
189	            if (s.contains(v.id + ":" + phase) || s.contains(v.id + ":denied")) return;
190	            s.add(v.id + ":" + phase);
191	            prefs(app).edit().putStringSet("sent", s).apply();
192	            app.getSystemService(NotificationManager.class).notify(TAG + v.id, 0, card(app, v, phase));
193	        }, token(v.id), SystemClock.uptimeMillis() + Math.max(0, delayMs));
194	    }
195	
196	    /** The one card for a call; each phase replaces it on its own channel (its own sound), with a live countdown until it runs. */
197	    static Notification card(Context c, HubRules.Veto v, String phase) {
198	        Intent open = new Intent(c, MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP | Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(MainActivity.EXTRA_VETO, v.id);
199	        PendingIntent tap = PendingIntent.getActivity(c, (TAG + v.id).hashCode(), open, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
200	        String what = v.command.isEmpty() ? v.tool : v.command;
201	        long runsAt = v.runsAtLocal();
202	        int left = (int) Math.max(0, Math.ceil((runsAt - System.currentTimeMillis()) / 1000.0));
203	        String title = "running".equals(phase) ? "Running now: " + v.title
204	            : "warning".equals(phase) ? left + " s left: " + v.title
205	            : "Runs in " + (left / 60) + ":" + String.format(java.util.Locale.ROOT, "%02d", left % 60) + ": " + v.title;
206	        NotificationCompat.Builder b = new NotificationCompat.Builder(c, channelId(c, phase))
207	            .setSmallIcon(R.mipmap.ic_launcher).setContentTitle(title).setContentText(what)
208	            .setStyle(new NotificationCompat.BigTextStyle().bigText(what + ("running".equals(phase) ? "" : "\nDeny to stop it.")))
209	            .setPriority(NotificationCompat.PRIORITY_HIGH).setCategory(NotificationCompat.CATEGORY_ALARM)
210	            .setContentIntent(tap).setAutoCancel("running".equals(phase))
211	            .setVisibility(NotificationCompat.VISIBILITY_PRIVATE)
212	            .setPublicVersion(new NotificationCompat.Builder(c, channelId(c, phase)).setSmallIcon(R.mipmap.ic_launcher).setContentTitle("Held command").build());
213	        if (!"running".equals(phase)) {
214	            b.setWhen(runsAt).setShowWhen(true).setUsesChronometer(true).setOngoing(true);
215	            if (Build.VERSION.SDK_INT >= 24) b.setChronometerCountDown(true);
216	            if (Build.VERSION.SDK_INT >= 26) b.setTimeoutAfter(Math.max(1000, runsAt - System.currentTimeMillis() + 5000));
217	            Intent deny = new Intent(c, Receiver.class).setAction(ACTION_DENY).putExtra(EXTRA_ID, v.id);
218	            PendingIntent pd = PendingIntent.getBroadcast(c, ("deny:" + v.id).hashCode(), deny, PendingIntent.FLAG_UPDATE_CURRENT | PendingIntent.FLAG_IMMUTABLE);
219	            b.addAction(0, "Deny", pd);
220	        }
221	        return b.build();
222	    }
223	
224	    /** A test of one phase's notification (Settings → Plugins → Approvals → Test). */
225	    static void test(Context c, String phase) {
226	        channels(c);
227	        HubRules.Veto v = new HubRules.Veto("00000000-0000-0000-0000-000000000000", null, "vps.run", "Test call", "echo hello",
228	            HubRules.HUB + HubRules.APPROVALS_PATH, "warning".equals(phase) ? 30 : "running".equals(phase) ? 0 : 180, System.currentTimeMillis());
229	        Notification n = card(c, v, phase);
230	        n.flags &= ~Notification.FLAG_ONGOING_EVENT;
231	        c.getSystemService(NotificationManager.class).notify("veto-test", 0, n);
232	    }
233	
234	    /* ---------------------------------------------------------------- deny */
235	
236	    /** Deny with the phone's hub session; on success the card says so (quietly) and every timer for it stops. 200 = denied. */
237	    static int deny(Context c, String id) {
238	        String hub = HubRules.HUB;
239	        int code = HubRules.deny(hub, id, CookieManager.getInstance().getCookie(hub));
240	        NotificationManager nm = c.getSystemService(NotificationManager.class);
241	        if (code == 200) {
242	            Set<String> s = sent(c);
243	            s.add(id + ":denied");
244	            prefs(c).edit().putStringSet("sent", s).apply();
245	            WatchService w = WatchService.running;
246	            if (w != null) w.cancelVeto(token(id));
247	            nm.notify(TAG + id, 0, new NotificationCompat.Builder(c, WatchService.CH_APPROVALS)
248	                .setSmallIcon(R.mipmap.ic_launcher).setContentTitle("Denied").setContentText("It will not run.")
249	                .setSilent(true).setAutoCancel(true).setTimeoutAfter(15_000).build());
250	        }
251	        return code;
252	    }
253	
254	    /** The notification's Deny action: runs off the main thread, then tells the app (if it's open). */
255	    public static final class Receiver extends BroadcastReceiver {
256	        @Override public void onReceive(Context context, Intent intent) {
257	            if (intent == null || !ACTION_DENY.equals(intent.getAction())) return;
258	            String id = intent.getStringExtra(EXTRA_ID);
259	            if (id == null) return;
260	            PendingResult done = goAsync();
261	            Context app = context.getApplicationContext();
262	            new Thread(() -> {
263	                try {
264	                    int code = deny(app, id);
265	                    AmberxNativePlugin.vetoEvent(id, code == 200 ? "denied" : "deny-failed", code == 200 ? null : (code < 0 ? "signed out of axHub" : "the hub answered " + code));
266	                    if (code != 200) {
267	                        Intent open = new Intent(app, HubWebActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK).putExtra(HubWebActivity.EXTRA_URL, HubRules.approvalUrl(HubRules.HUB, id));
268	                        try { app.startActivity(open); } catch (Exception ignored) { /* background start refused */ }
269	                    }
270	                } finally {
271	                    done.finish();
272	                }
273	            }, "amberx-veto-deny").start();
274	        }
275	    }
276	}
