            JSONObject k = known.optJSONObject(id);
            boolean quiet = was.contains(id + ":denied") || was.contains(id + ":approved") || was.contains(id + ":shelved");
            boolean due = k != null && k.optLong("runsAt", Long.MAX_VALUE) - 3000 <= now && !quiet;
