        try { seen.put(v.id, new JSONObject().put("title", v.title).put("command", v.command).put("url", v.url).put("runsAt", v.runsAtLocal())); } catch (Exception ignored) {}
        prefs(c).edit().putString("known", seen.toString()).apply();
    }

