            String what = intent.getAction();
            String action = ACTION_DENY.equals(what) ? "deny" : ACTION_APPROVE.equals(what) ? "approve-now" : ACTION_SHELVE.equals(what) ? "shelve" : null;
            String id = intent.getStringExtra(EXTRA_ID);
